(95, 1, '2026-08-14 22:24:55', '2026-08-14 22:24:55', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<main class=\"wp-block-group\">\n	<!-- Section order follows the Homepage Blueprint (updated 2026-08-19):\n	     Meet Tanya moved back to blueprint position seven, per Tanya\'s\n	     request to lead with the consumer-facing hero and value sections\n	     rather than the agent bio. -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-home-hero\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/hero\",\"name\":\"Homepage Hero\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-home-hero has-alabaster-background-color has-background\">\n\n	<!-- wp:html -->\n	<img\n		class=\"tb-home-hero__image\"\n		src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-hero.jpg\"\n		alt=\"\"\n		width=\"1720\"\n		height=\"914\"\n		fetchpriority=\"high\"\n		decoding=\"async\"\n	/>\n	<!-- /wp:html -->\n\n	<!-- wp:group {\"className\":\"tb-home-hero__inner\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-home-hero__inner\">\n\n		<!-- wp:group {\"className\":\"tb-home-hero__content tb-hero-arrive\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-home-hero__content tb-hero-arrive\">\n\n			<!-- The blueprint headline is a full sentence and the page may only\n			     carry one H1, so the script accent lives inside the heading\n			     rather than as a separate line above it. -->\n			<!-- wp:heading {\"level\":1,\"className\":\"tb-home-hero__title\"} -->\n			<h1 class=\"wp-block-heading tb-home-hero__title\"><span class=\"tb-script-accent\" style=\"text-transform:none\">Helping you</span> love your home<br>and where you live.</h1>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"tb-home-hero__dek\"} -->\n			<p class=\"tb-home-hero__dek\">Serving buyers and sellers in Renton and throughout the Puget Sound region.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:buttons {\"className\":\"tb-home-hero__buttons\",\"style\":{\"spacing\":{\"blockGap\":\"0.75rem\",\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n			<div class=\"wp-block-buttons tb-home-hero__buttons\" style=\"margin-top:var(--wp--preset--spacing--40)\">\n				<!-- wp:button {\"backgroundColor\":\"charcoal\"} -->\n				<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-charcoal-background-color has-background wp-element-button\" href=\"/contact/\">Let’s Talk About Your Next Move</a></div>\n				<!-- /wp:button -->\n\n								<!-- wp:button {\"className\":\"tb-button-outline\",\"textColor\":\"charcoal\"} -->\n				<div class=\"wp-block-button tb-button-outline\"><a class=\"wp-block-button__link has-charcoal-color has-text-color wp-element-button\" href=\"/renton/\">Explore Renton</a></div>\n				<!-- /wp:button -->\n			</div>\n			<!-- /wp:buttons -->\n\n		</div>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-stats-band\",\"backgroundColor\":\"charcoal\",\"textColor\":\"base\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"},\"metadata\":{\"patternName\":\"tanya-barrans/stats\",\"name\":\"Track Record\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-stats-band has-base-color has-charcoal-background-color has-text-color has-background\">\n\n	<!-- wp:heading {\"level\":2,\"className\":\"tb-sr-only\"} -->\n	<h2 class=\"wp-block-heading tb-sr-only\">Tanya\'s track record</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:columns {\"align\":\"wide\",\"className\":\"tb-stats-band__grid\"} -->\n	<div class=\"wp-block-columns alignwide tb-stats-band__grid\">\n\n		<!-- wp:column {\"className\":\"tb-stat-item tb-reveal\"} -->\n		<div class=\"wp-block-column tb-stat-item tb-reveal\">\n			<!-- wp:html -->\n			<div class=\"tb-stat-item__icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\"></rect><path d=\"M3 10h18\"></path><path d=\"M8 3v4\"></path><path d=\"M16 3v4\"></path></svg></div>\n			<!-- /wp:html -->\n			<!-- wp:paragraph {\"className\":\"tb-stat\"} -->\n			<p class=\"tb-stat\">7+</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-stat-item__label\"} -->\n			<p class=\"tb-stat-item__label\">Years of Experience</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-stat-item tb-reveal\"} -->\n		<div class=\"wp-block-column tb-stat-item tb-reveal\">\n			<!-- wp:html -->\n			<div class=\"tb-stat-item__icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 11l9-8 9 8\"></path><path d=\"M5 10v10h14V10\"></path><path d=\"M9 20v-6h6v6\"></path></svg></div>\n			<!-- /wp:html -->\n			<!-- wp:paragraph {\"className\":\"tb-stat\"} -->\n			<p class=\"tb-stat\">70+</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-stat-item__label\"} -->\n			<p class=\"tb-stat-item__label\">Homes Sold</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-stat-item tb-reveal\"} -->\n		<div class=\"wp-block-column tb-stat-item tb-reveal\">\n			<!-- wp:html -->\n			<div class=\"tb-stat-item__icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 3l2.6 5.6 6.1.5-4.6 4 1.4 6-5.5-3.3L6.5 19l1.4-6-4.6-4 6.1-.5L12 3z\"></path></svg></div>\n			<!-- /wp:html -->\n			<!-- wp:paragraph {\"className\":\"tb-stat\"} -->\n			<p class=\"tb-stat\">39</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-stat-item__label\"} -->\n			<p class=\"tb-stat-item__label\">5-Star Google Reviews</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-stat-item tb-reveal\"} -->\n		<div class=\"wp-block-column tb-stat-item tb-reveal\">\n			<!-- wp:html -->\n			<div class=\"tb-stat-item__icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 17l6-6 4 4 8-8\"></path><path d=\"M15 7h6v6\"></path></svg></div>\n			<!-- /wp:html -->\n			<!-- wp:paragraph {\"className\":\"tb-stat\"} -->\n			<p class=\"tb-stat\">$65M</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-stat-item__label\"} -->\n			<p class=\"tb-stat-item__label\">In Sales Volume</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n	</div>\n	<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-ways\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1320px\"},\"metadata\":{\"patternName\":\"tanya-barrans/pathways\",\"name\":\"Three Ways Tanya Helps\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-ways has-base-background-color has-background\">\n\n	<!-- wp:heading {\"level\":2,\"textAlign\":\"center\",\"className\":\"tb-ways__title\"} -->\n	<h2 class=\"wp-block-heading has-text-align-center tb-ways__title\">Three ways Tanya helps</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:group {\"align\":\"wide\",\"className\":\"tb-ways__grid\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group alignwide tb-ways__grid\">\n\n		<!-- wp:group {\"className\":\"tb-way tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-way tb-reveal\">\n			<!-- wp:html -->\n			<img class=\"tb-way__photo\" src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-front-door.jpg\" alt=\"\" width=\"900\" height=\"1125\" loading=\"lazy\" decoding=\"async\" />\n			<!-- /wp:html -->\n			<!-- wp:heading {\"level\":3,\"className\":\"tb-way__title\"} -->\n			<h3 class=\"wp-block-heading tb-way__title\">Buy With Confidence</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"tb-way__copy\"} -->\n			<p class=\"tb-way__copy\">Find the right home, neighborhood, and long-term fit.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-way__link\"} -->\n			<p class=\"tb-way__link\"><a href=\"/buy/\">Start Your Home Search <span aria-hidden=\"true\">&rarr;</span></a></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:group {\"className\":\"tb-way tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-way tb-reveal\">\n			<!-- wp:html -->\n			<img class=\"tb-way__photo\" src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg\" alt=\"\" width=\"900\" height=\"1125\" loading=\"lazy\" decoding=\"async\" />\n			<!-- /wp:html -->\n			<!-- wp:heading {\"level\":3,\"className\":\"tb-way__title\"} -->\n			<h3 class=\"wp-block-heading tb-way__title\">Sell With Strategy</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"tb-way__copy\"} -->\n			<p class=\"tb-way__copy\">Clear pricing, thoughtful preparation, and marketing built to make your home stand out.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-way__link\"} -->\n			<p class=\"tb-way__link\"><a href=\"/sell/\">Explore My Selling Plan <span aria-hidden=\"true\">&rarr;</span></a></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:group {\"className\":\"tb-way tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-way tb-reveal\">\n			<!-- wp:html -->\n			<img class=\"tb-way__photo\" src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-kitchen-garden.jpg\" alt=\"\" width=\"900\" height=\"1125\" loading=\"lazy\" decoding=\"async\" />\n			<!-- /wp:html -->\n			<!-- wp:heading {\"level\":3,\"className\":\"tb-way__title\"} -->\n			<h3 class=\"wp-block-heading tb-way__title\">Love Where You Live Now</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"tb-way__copy\"} -->\n			<p class=\"tb-way__copy\">Home projects, garden ideas, local guides, and practical homeowner resources.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-way__link\"} -->\n			<p class=\"tb-way__link\"><a href=\"/blog/\">Browse the Journal <span aria-hidden=\"true\">&rarr;</span></a></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-editorial-feature tb-editorial-feature\\u002d\\u002dphoto-right tb-real-estate-feature\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/listings-placeholder\",\"name\":\"Real Estate Guidance\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-editorial-feature tb-editorial-feature--photo-right tb-real-estate-feature has-alabaster-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-editorial-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-editorial-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-front-door.jpg);background-position:center\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-editorial-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-editorial-feature__content tb-reveal\">\n\n		<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n		<p class=\"tb-eyebrow\">Real Estate</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"xx-large\"} -->\n		<h2 class=\"wp-block-heading has-xx-large-font-size\">Your next move should feel <em style=\"color:var(--wp--preset--color--sage)\">clear.</em></h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Whether you are buying your first home, selling a place filled with memories, or simply wondering whether now is the right time, you deserve a strategy built around your goals—not a one-size-fits-all plan.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:group {\"className\":\"tb-real-estate-links\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n		<div class=\"wp-block-group tb-real-estate-links\">\n			<!-- wp:paragraph -->\n			<p><a href=\"/buy/\">Buying a Home <span aria-hidden=\"true\">→</span></a></p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p><a href=\"/sell/\">Selling a Home <span aria-hidden=\"true\">→</span></a></p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p><a href=\"/listings/\">View Listings <span aria-hidden=\"true\">→</span></a></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-brand-pillars\",\"backgroundColor\":\"charcoal\",\"textColor\":\"base\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"},\"metadata\":{\"patternName\":\"tanya-barrans/credibility\",\"name\":\"Brand Promise\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-brand-pillars has-base-color has-charcoal-background-color has-text-color has-background\">\n\n	<!-- wp:heading {\"level\":2,\"className\":\"tb-sr-only\"} -->\n	<h2 class=\"wp-block-heading tb-sr-only\">What you can expect from Tanya</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:columns {\"align\":\"wide\",\"className\":\"tb-brand-pillars__grid\"} -->\n	<div class=\"wp-block-columns alignwide tb-brand-pillars__grid\">\n\n		<!-- wp:column {\"className\":\"tb-brand-pillar tb-reveal\"} -->\n		<div class=\"wp-block-column tb-brand-pillar tb-reveal\">\n			<!-- wp:paragraph {\"className\":\"tb-brand-pillar__label\"} -->\n			<p class=\"tb-brand-pillar__label\">Clear Advice</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p>Practical answers that help you make a decision you will still feel good about years from now.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-brand-pillar tb-reveal\"} -->\n		<div class=\"wp-block-column tb-brand-pillar tb-reveal\">\n			<!-- wp:paragraph {\"className\":\"tb-brand-pillar__label\"} -->\n			<p class=\"tb-brand-pillar__label\">Local Knowledge</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p>Neighborhood context, market perspective, and the everyday details that shape where you live.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-brand-pillar tb-reveal\"} -->\n		<div class=\"wp-block-column tb-brand-pillar tb-reveal\">\n			<!-- wp:paragraph {\"className\":\"tb-brand-pillar__label\"} -->\n			<p class=\"tb-brand-pillar__label\">Real Relationships</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p>Responsive, honest guidance built around your family, your goals, and what matters after closing.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n	</div>\n	<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-story-quote\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull tb-story-quote has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-story-quote__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-story-quote__content tb-reveal\">\n\n		<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n		<p class=\"tb-eyebrow\">What Clients Remember</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"className\":\"tb-story-quote__mark\"} -->\n		<p class=\"tb-story-quote__mark\" aria-hidden=\"true\">“</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:quote {\"className\":\"tb-story-quote__quote\"} -->\n		<blockquote class=\"wp-block-quote tb-story-quote__quote\"><p>By the end, you felt like family.</p></blockquote>\n		<!-- /wp:quote -->\n\n				<!-- wp:paragraph {\"textColor\":\"charcoal\"} -->\n		<p class=\"has-charcoal-color has-text-color\">“Tanya did an amazing job selling our home. She made sure it was picture ready for getting the maximum possible price for the market. When we ran into snags she went above and beyond to fix them for us. She was available for any questions or concerns we may have had. When it came time to negotiate, she got the best price for us.”</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"className\":\"tb-story-quote__attribution\",\"textColor\":\"charcoal\",\"fontSize\":\"small\"} -->\n		<p class=\"tb-story-quote__attribution has-charcoal-color has-text-color has-small-font-size\">Christian Herzberger · Google review</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"className\":\"tb-text-link\"} -->\n		<p class=\"tb-text-link\"><a href=\"https://g.page/r/CTDpOcL-7SDkEAE\" target=\"_blank\" rel=\"noopener noreferrer\">Read Tanya’s Google reviews <span aria-hidden=\"true\">→</span></a></p>\n		<!-- /wp:paragraph -->\n\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-story-quote__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-story-quote__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg)\"></div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"tb-quote-row-section tb-home-reviews\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull tb-quote-row-section tb-home-reviews has-alabaster-background-color has-background\">\n	<div class=\"tb-page-shell\">\n		<!-- wp:paragraph {\"className\":\"tb-eyebrow\",\"align\":\"center\"} -->\n		<p class=\"tb-eyebrow has-text-align-center\">What Clients Are Saying</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:shortcode -->\n[trustindex data-widget-id=f67a0f279ba6760db346a7f2d42]\n		<!-- /wp:shortcode -->\n	</div>\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-editorial-feature tb-editorial-feature\\u002d\\u002dphoto-left tb-about-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/about-intro\",\"name\":\"About Intro\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-editorial-feature tb-editorial-feature--photo-left tb-about-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-editorial-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-editorial-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/uploads/2026/07/about-main.jpg);background-position:center 20%\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-editorial-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-editorial-feature__content tb-reveal\">\n\n		<!-- wp:paragraph {\"className\":\"tb-eyebrow\",\"textColor\":\"dusty-blush\"} -->\n		<p class=\"tb-eyebrow has-dusty-blush-color has-text-color\">Meet Tanya</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"xx-large\"} -->\n		<h2 class=\"wp-block-heading has-xx-large-font-size\">Real estate is personal.<br><em>Your guidance should be, too.</em></h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Buying or selling a home is exciting, stressful, emotional, and sometimes downright overwhelming. Tanya’s goal is to make sure you never feel like you are navigating it alone.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">You will get honest advice, quick answers, plenty of laughs, and someone who genuinely cares about the outcome—not just the closing date.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n		<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--40)\">\n			<!-- wp:button {\"backgroundColor\":\"charcoal\",\"textColor\":\"base\"} -->\n			<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-base-color has-charcoal-background-color has-text-color has-background wp-element-button\" href=\"/about/\">Meet Tanya</a></div>\n			<!-- /wp:button -->\n		</div>\n		<!-- /wp:buttons -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"tb-journal-section\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"},\"metadata\":{\"patternName\":\"tanya-barrans/blog-teaser\",\"name\":\"Latest From the Journal\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-journal-section has-alabaster-background-color has-background\">\n\n	<!-- wp:group {\"align\":\"wide\",\"className\":\"tb-journal-section__header\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\",\"verticalAlignment\":\"bottom\"}} -->\n	<div class=\"wp-block-group alignwide tb-journal-section__header\">\n		<!-- wp:group {\"className\":\"tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-reveal\">\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">The Journal</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:heading {\"fontSize\":\"xx-large\"} -->\n			<h2 class=\"wp-block-heading has-xx-large-font-size\">Latest from the Journal</h2>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n			<p class=\"has-graphite-color has-text-color\">The Journal is the blog: practical ideas for real estate, decorating, gardening, food, homeownership, and everyday life. Rooted in Renton is reserved for local stories and neighborhood guides.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:paragraph {\"className\":\"tb-text-link\"} -->\n		<p class=\"tb-text-link\"><a href=\"/blog/\">Explore the Journal <span aria-hidden=\"true\">→</span></a></p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:query {\"queryId\":1,\"query\":{\"perPage\":3,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\"},\"align\":\"wide\",\"className\":\"tb-journal-query\"} -->\n	<div class=\"wp-block-query alignwide tb-journal-query\">\n		<!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n\n			<!-- wp:group {\"className\":\"tb-journal-card tb-reveal\",\"layout\":{\"type\":\"constrained\"}} -->\n			<div class=\"wp-block-group tb-journal-card\">\n				<!-- wp:post-featured-image {\"aspectRatio\":\"4/3\",\"isLink\":true} /-->\n				<!-- wp:group {\"className\":\"tb-journal-card__content\",\"layout\":{\"type\":\"constrained\"}} -->\n				<div class=\"wp-block-group tb-journal-card__content\">\n					<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-card__category\"} /-->\n					<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"large\"} /-->\n					<!-- wp:post-date {\"textColor\":\"graphite\",\"fontSize\":\"small\"} /-->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:group -->\n\n		<!-- /wp:post-template -->\n	</div>\n	<!-- /wp:query -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-newsletter-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/newsletter\",\"name\":\"Newsletter Signup\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-newsletter-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg)\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__content tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\"} -->\n		<p class=\"tb-script-accent\">Let’s stay in touch</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Notes worth opening.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Useful home ideas, local stories, and honest real estate guidance—delivered with no pressure and no polished filler.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:html -->\n		<form class=\"tb-newsletter-form\" novalidate>\n			<div class=\"tb-newsletter-fields\">\n				<label class=\"tb-sr-only\" for=\"tb-nl-name\">First name</label>\n				<input type=\"text\" id=\"tb-nl-name\" name=\"name\" class=\"tb-newsletter-input\" placeholder=\"First name\" autocomplete=\"given-name\" />\n\n				<label class=\"tb-sr-only\" for=\"tb-nl-email\">Email address</label>\n				<input type=\"email\" id=\"tb-nl-email\" name=\"email\" class=\"tb-newsletter-input\" placeholder=\"Email address\" autocomplete=\"email\" required />\n\n				<div class=\"tb-newsletter-hp\" aria-hidden=\"true\">\n					<label for=\"tb-nl-website\">Website</label>\n					<input type=\"text\" id=\"tb-nl-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" />\n				</div>\n\n				<button type=\"submit\" class=\"tb-newsletter-submit\">Subscribe</button>\n			</div>\n			<p class=\"tb-newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n		</form>\n		<!-- /wp:html -->\n\n		<!-- wp:paragraph {\"className\":\"tb-newsletter-feature__privacy\"} -->\n		<p class=\"tb-newsletter-feature__privacy\">No spam. Unsubscribe whenever you like.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-closing-cta\",\"backgroundColor\":\"alabaster\",\"textColor\":\"charcoal\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"920px\"},\"metadata\":{\"patternName\":\"tanya-barrans/cta\",\"name\":\"Contact CTA Band\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-closing-cta has-charcoal-color has-alabaster-background-color has-text-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-closing-cta__inner tb-reveal\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"760px\"}} -->\n	<div class=\"wp-block-group tb-closing-cta__inner tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\",\"textColor\":\"charcoal\"} -->\n		<p class=\"tb-script-accent has-charcoal-color has-text-color\">When you’re ready</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"xx-large\",\"textColor\":\"charcoal\"} -->\n		<h2 class=\"wp-block-heading has-text-align-center has-charcoal-color has-text-color has-xx-large-font-size\">Your next move should support the life you want to live.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"charcoal\"} -->\n		<p class=\"has-text-align-center has-charcoal-color has-text-color\">Whether you are three years or three weeks from a move, Tanya will give you an honest look at your options—without pressure.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"flexWrap\":\"wrap\"},\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n		<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--40)\">\n			<!-- wp:button {\"backgroundColor\":\"charcoal\",\"textColor\":\"base\"} -->\n			<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-base-color has-charcoal-background-color has-text-color has-background wp-element-button\" href=\"/contact/\">Tell Me What You’re Planning</a></div>\n			<!-- /wp:button -->\n			<!-- wp:button {\"className\":\"tb-button-outline\",\"textColor\":\"charcoal\"} -->\n			<div class=\"wp-block-button tb-button-outline\"><a class=\"wp-block-button__link has-charcoal-color has-text-color wp-element-button\" href=\"https://calendar.app.google/zndHShd1Rm6W6Qb38\" target=\"_blank\" rel=\"noopener noreferrer\">Schedule a Conversation</a></div>\n			<!-- /wp:button -->\n		</div>\n		<!-- /wp:buttons -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n\n\n<!-- wp:html -->\n<script defer async src=\"https://cdn.trustindex.io/loader-cert.js?1c1116f795cd76061386b3bd8ca\"></script>\n<!-- /wp:html -->\n', 'Front Page', 'Displays your site\'s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.', 'publish', 'closed', 'closed', '', 'front-page', '', '', '2026-08-21 18:19:55', '2026-08-21 18:19:55', '', 0, 'https://violet-wren-104886.hostingersite.com/front-page/', 0, 'wp_template', '', 0),
(96, 1, '2026-08-14 22:25:36', '2026-08-14 22:25:36', '<!-- wp:pattern {\"slug\":\"tanya-barrans/about-intro\"} /-->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"720px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--40)\">\n\n	<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-eyebrow\",\"textColor\":\"dusty-blush\"} -->\n<p class=\"has-text-align-center tb-eyebrow has-dusty-blush-color has-text-color\">Your Local Real Estate Expert</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:heading {\"level\":1,\"textAlign\":\"center\",\"fontSize\":\"x-large\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<h1 class=\"wp-block-heading has-text-align-center has-x-large-font-size\" style=\"margin-bottom:var(--wp--preset--spacing--40)\">Real relationships. Remarkable results.</h1>\n<!-- /wp:heading -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">Buying or selling a home is one of the biggest decisions you\'ll make, and it shouldn\'t feel like you\'re figuring it out alone. Whether you\'re searching for your first home, selling the place where you\'ve made years of memories, or simply wondering if now is the right time to make a move, my job is to give you honest advice, a smart strategy, and the confidence to move forward.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">I\'ve built my business around knowing the communities I serve — not just the statistics, but the neighborhoods, schools, commute patterns, hidden gems, and market trends that help my clients make better decisions. From Renton and Kent to Maple Valley, Covington, Newcastle, and the surrounding communities, I know what makes each area unique because this is home, too.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">Every client receives a customized marketing and pricing strategy designed around their goals, not a one-size-fits-all plan. Professional photography, Zillow Showcase, video, digital marketing, and strategic negotiation all work together to help you achieve the best possible outcome.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">But here\'s what I hope you\'ll remember most. By the time we get to closing, there\'s a good chance we\'ll be talking about more than real estate. I\'ll probably have you planning your first vegetable garden, convincing you to try homemade sourdough, or texting you recommendations for the best local spots after you\'ve moved in. Because while I love helping people buy and sell homes, my favorite part has always been the relationships that come with it.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">Many of my clients become friends, and some of my favorite compliments have nothing to do with the sale itself. They’re the messages that say, <em>“We couldn’t imagine going through this without you,”</em> or <em>“By the end, you felt like family.”</em></p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"align\":\"center\",\"fontFamily\":\"serif\",\"style\":{\"typography\":{\"fontStyle\":\"italic\",\"fontSize\":\"1.375rem\",\"lineHeight\":\"1.5\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n	<p class=\"has-text-align-center has-serif-font-family\" style=\"margin-top:var(--wp--preset--spacing--40);font-size:1.375rem;font-style:italic;line-height:1.5\">My goal isn\'t just to help you find the right house. It\'s to help you feel at home long before you unpack the first box.</p>\n	<!-- /wp:paragraph -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull has-alabaster-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--40)\">\n\n	<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-eyebrow\"} -->\n	<p class=\"has-text-align-center tb-eyebrow\">A Little More Personality</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"xx-large\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|40\"}}}} -->\n	<h2 class=\"wp-block-heading has-text-align-center has-xx-large-font-size\" style=\"margin-bottom:var(--wp--preset--spacing--40)\">Real estate, minus the stuffiness</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|30\"}}}} -->\n	<div class=\"wp-block-columns alignwide\">\n\n		<!-- wp:column {\"className\":\"tb-reveal\"} -->\n		<div class=\"wp-block-column tb-reveal\">\n			<!-- wp:image {\"id\":19,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"tb-card\",\"style\":{\"border\":{\"radius\":\"4px\"}}} -->\n			<figure class=\"wp-block-image size-full tb-card has-custom-border\"><img src=\"https://tanyabarrans.com/wp-content/uploads/2026/07/gallery-1.jpg\" alt=\"Tanya Barrans smiling, seated\" class=\"wp-image-19\" style=\"border-radius:4px;aspect-ratio:3/4;object-fit:cover;width:100%\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-reveal\"} -->\n		<div class=\"wp-block-column tb-reveal\">\n			<!-- wp:image {\"id\":25,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"tb-card\",\"style\":{\"border\":{\"radius\":\"4px\"}}} -->\n			<figure class=\"wp-block-image size-full tb-card has-custom-border\"><img src=\"https://tanyabarrans.com/wp-content/uploads/2026/07/gallery-2-new.jpg\" alt=\"Tanya Barrans smiling, hands on hips\" class=\"wp-image-25\" style=\"border-radius:4px;aspect-ratio:3/4;object-fit:cover;width:100%\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-reveal\"} -->\n		<div class=\"wp-block-column tb-reveal\">\n			<!-- wp:image {\"id\":21,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"tb-card\",\"style\":{\"border\":{\"radius\":\"4px\"}}} -->\n			<figure class=\"wp-block-image size-full tb-card has-custom-border\"><img src=\"https://tanyabarrans.com/wp-content/uploads/2026/07/gallery-3.jpg\" alt=\"Tanya Barrans laughing, full length\" class=\"wp-image-21\" style=\"border-radius:4px;aspect-ratio:3/4;object-fit:cover;width:100%;object-position:top\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:column -->\n\n	</div>\n	<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n', 'About', '', 'inherit', 'closed', 'closed', '', '6-revision-v1', '', '', '2026-08-14 22:25:36', '2026-08-14 22:25:36', '', 6, 'https://violet-wren-104886.hostingersite.com/?p=96', 0, 'revision', '', 0),
(97, 1, '2026-08-14 22:26:05', '2026-08-14 22:26:05', '<!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\">\n\n	<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"120px\"} -->\n	<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:120px\">\n		<!-- wp:image {\"id\":18,\"width\":\"120px\",\"height\":\"120px\",\"sizeSlug\":\"medium\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"999px\"}}} -->\n		<figure class=\"wp-block-image size-medium is-resized has-custom-border\"><img src=\"https://tanyabarrans.com/wp-content/uploads/2026/07/contact-circle-300x300.jpg\" alt=\"Tanya Barrans, Puget Sound real estate broker\" class=\"wp-image-18\" style=\"border-radius:999px;width:120px;height:120px;object-fit:cover\"/></figure>\n		<!-- /wp:image -->\n	</div>\n	<!-- /wp:column -->\n\n	<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n	<div class=\"wp-block-column is-vertically-aligned-center\">\n		<!-- wp:heading {\"level\":1,\"fontSize\":\"x-large\"} -->\n		<h1 class=\"wp-block-heading has-x-large-font-size\">Tell me what you are trying to solve.</h1>\n		<!-- /wp:heading -->\n		<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n		<p class=\"has-muted-color has-text-color\">Whether you have a specific question or just want to explore what\'s possible, reach out anytime.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:column -->\n\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p><strong>Email:</strong> <a href=\"mailto:tanya@tanyabarrans.com\">tanya@tanyabarrans.com</a><br><strong>Phone:</strong> <a href=\"tel:+14255374728\">(425) 537-4728</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--30)\">\n	<!-- wp:button {\"className\":\"tb-button-outline\",\"textColor\":\"ink\"} -->\n	<div class=\"wp-block-button tb-button-outline\"><a class=\"wp-block-button__link has-ink-color has-text-color wp-element-button\" href=\"https://calendar.app.google/zndHShd1Rm6W6Qb38\" target=\"_blank\" rel=\"noopener noreferrer\">Schedule a Call →</a></div>\n	<!-- /wp:button -->\n</div>\n<!-- /wp:buttons -->\n\n<!-- wp:paragraph {\"className\":\"tb-eyebrow\",\"textColor\":\"dusty-blush\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<p class=\"tb-eyebrow has-dusty-blush-color has-text-color\" style=\"margin-top:var(--wp--preset--spacing--40);margin-bottom:var(--wp--preset--spacing--20)\">Follow Along</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n<div class=\"tb-social-icons tb-social-icons--contact\">\n	<a href=\"https://www.facebook.com/tanyabarrans\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Tanya Barrans on Facebook\" class=\"tb-social-icon\">\n		<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M22 12.06C22 6.5 17.52 2 12 2S2 6.5 2 12.06c0 5 3.66 9.15 8.44 9.94v-7.03H7.9v-2.91h2.54V9.85c0-2.5 1.49-3.89 3.77-3.89 1.09 0 2.24.2 2.24.2v2.46h-1.26c-1.24 0-1.63.77-1.63 1.56v1.88h2.78l-.44 2.91h-2.34V22c4.78-.79 8.44-4.94 8.44-9.94Z\"/></svg>\n	</a>\n	<a href=\"https://www.instagram.com/tanyabarrans/\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Tanya Barrans on Instagram\" class=\"tb-social-icon\">\n		<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/><circle cx=\"17.5\" cy=\"6.5\" r=\"1\"/></svg>\n	</a>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"tb-content-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"var:preset|spacing|50\"}},\"border\":{\"radius\":\"8px\"}},\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group tb-content-card has-alabaster-background-color has-background\" style=\"border-radius:8px;margin-top:var(--wp--preset--spacing--50);padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\">\n	<!-- wp:pattern {\"slug\":\"tanya-barrans/contact-form\"} /-->\n</div>\n<!-- /wp:group -->\n', 'Contact', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-08-14 22:26:05', '2026-08-14 22:26:05', '', 11, 'https://violet-wren-104886.hostingersite.com/?p=97', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(98, 1, '2026-08-14 22:26:18', '2026-08-14 22:26:18', '\n<!-- wp:paragraph -->\n<p><em>Last updated 12 August 2026.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>This policy explains what information this website collects, why it is collected, and what happens to it. It is written to describe how the site actually works rather than to cover every possibility in the abstract. If anything here is unclear, please ask — the contact details are at the bottom.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Who runs this website</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>This site belongs to Tanya Barrans, a licensed real estate broker in Washington State, brokered by John L Scott Real Estate. Each John L Scott office is independently owned and operated. Tanya is responsible for the information collected here.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">What this site collects, and when</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">When you send a message through the contact form</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>The contact form asks for your name and email address, and optionally your phone number, what you are thinking about, your timing, how you prefer to be contacted, and anything you would like Tanya to know. All of it is voluntary apart from your name and email, which are needed in order to reply.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>What you send is stored in Follow Up Boss, the client management system Tanya uses to keep track of conversations. It is used to answer your enquiry and to follow up about it. Nothing you send through this form is added to a marketing mailing list unless you separately sign up for the newsletter.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">When you sign up for the newsletter</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>The newsletter form asks for your email address and, optionally, your first name. These are stored in Flodesk, the email service used to send the newsletter, and are used only to send it. Every newsletter includes an unsubscribe link, and unsubscribing takes effect immediately.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">When you simply browse</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>This site uses Google Analytics to understand how the site is used in aggregate — which pages are read, roughly where visitors come from, and whether anything is broken. Google Analytics sets cookies and collects information such as your approximate location, device and browser, and the pages you visit. It is used to improve the site, not to identify you personally.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>You can opt out of Google Analytics entirely by installing the <a href=\"https://tools.google.com/dlpage/gaoptout\" target=\"_blank\" rel=\"noopener noreferrer\">Google Analytics Opt-out Browser Add-on</a>, or by blocking cookies in your browser settings. The site works normally either way.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Like almost all websites, the web server also keeps standard technical logs — IP address, browser type, and the time of each request — which are used for security and troubleshooting.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">When you use tools embedded from other companies</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Two tools on this site are run by other companies, and using them means dealing with those companies directly as well:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\">\n<li><strong>Homebot</strong> — the home value and buying power tools on the Buying and Selling pages are provided by Homebot and appear inside a frame on this site. Anything you enter into those tools goes to Homebot under their own privacy policy.</li>\n<li><strong>Google Calendar scheduling</strong> — booking a conversation with Tanya uses a Google scheduling page. What you enter there is processed by Google.</li>\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Who your information is shared with</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Your information is never sold, rented, or traded.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>It is shared only with the service providers that make the site work — Follow Up Boss, Flodesk, Google Analytics, Homebot, and the company hosting the website — and only so they can perform that service. It may also be shared where the law requires it, or with a lender, title company, inspector, or brokerage staff when that is a necessary part of a transaction you have asked Tanya to help with.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">How long it is kept</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Enquiries and client records are kept for as long as needed to work with you and afterwards for as long as real estate record-keeping rules require. Newsletter subscriptions are kept until you unsubscribe. You may ask for your information to be deleted at any time, and it will be unless a law or a records requirement means it has to be kept.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Your choices</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\">\n<li>Unsubscribe from the newsletter using the link in any email.</li>\n<li>Ask what information is held about you, or ask for it to be corrected or deleted, by emailing Tanya.</li>\n<li>Ask to stop being contacted at any time.</li>\n<li>Turn off analytics cookies using the opt-out link above or your browser settings.</li>\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Requests are honoured regardless of where you live. There is no need to explain why you are asking.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Security</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>The site is served over an encrypted connection, and form submissions are sent to the systems above over encrypted connections. No website can promise perfect security, but access to the systems holding your information is limited to Tanya and the people who need it to help with your enquiry.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Children</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>This site is meant for adults and is not directed at children under 13. If a child has sent information through the site, please get in touch and it will be deleted.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Changes to this policy</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If the site starts collecting something new, or starts using a new service, this page will be updated and the date at the top will change.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Getting in touch</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Questions about this policy, or about information held about you, can go to:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Tanya Barrans<br>Email: <a href=\"mailto:tanya@tanyabarrans.com\">tanya@tanyabarrans.com</a><br>Phone: <a href=\"tel:+14255374728\">(425) 537-4728</a><br>Brokered by John L Scott Real Estate</p>\n<!-- /wp:paragraph -->\n', 'Privacy Policy', '', 'inherit', 'closed', 'closed', '', '3-revision-v1', '', '', '2026-08-14 22:26:18', '2026-08-14 22:26:18', '', 3, 'https://violet-wren-104886.hostingersite.com/?p=98', 0, 'revision', '', 0),
(99, 1, '2026-08-14 22:27:31', '2026-08-14 22:27:31', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:html -->\n<style id=\"tb-blog-template-styles\">\n/* Shared Journal article template - applies to every post using Single Posts */\n.tb-article-page {\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  color: #25364a;\n  overflow: hidden;\n}\n.tb-article-header {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(64px, 8vw, 112px) 0 44px;\n  text-align: center;\n}\n.tb-article-title {\n  max-width: 820px;\n  margin-left: auto !important;\n  margin-right: auto !important;\n  line-height: 1.04 !important;\n}\n.tb-article-dek {\n  max-width: 680px;\n  margin: 22px auto 0 !important;\n  font-size: clamp(18px, 2vw, 23px);\n  line-height: 1.55;\n}\n.tb-article-hero {\n  width: 100%;\n  max-width: none !important;\n  padding: 0 24px clamp(48px, 6vw, 80px);\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  box-sizing: border-box;\n}\n.tb-article-hero .wp-block-post-featured-image {\n  width: min(1040px, 100%);\n  margin: 0 auto !important;\n}\n.tb-article-hero .wp-block-post-featured-image img {\n  display: block;\n  width: 100%;\n  height: clamp(360px, 52vw, 620px);\n  object-fit: cover;\n  border-radius: 18px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.13);\n}\n.tb-article-body {\n  width: min(720px, calc(100% - 48px));\n  margin: 0 auto;\n  padding-bottom: clamp(72px, 9vw, 120px);\n  font-size: 18px;\n  line-height: 1.78;\n}\n.tb-article-body h2 {\n  margin-top: 2.4em;\n  color: #344c6a;\n}\n.tb-article-body .alignwide {\n  width: min(1040px, calc(100vw - 48px));\n  max-width: none;\n  margin-left: 50% !important;\n  transform: translateX(-50%);\n}\n.tb-article-body figure img {\n  border-radius: 14px;\n}\n.tb-article-explore {\n  padding: clamp(64px, 8vw, 96px) 24px !important;\n  background: #344c6a !important;\n}\n.tb-article-explore .tb-page-shell {\n  width: min(940px, 100%);\n  margin: 0 auto;\n}\n.tb-article-explore__links {\n  max-width: 820px;\n  margin: 34px auto 0;\n}\n.tb-newsletter-feature {\n  width: min(1040px, calc(100% - 48px)) !important;\n  max-width: 1040px !important;\n  min-height: 420px;\n  margin: clamp(72px, 9vw, 112px) auto !important;\n  display: grid !important;\n  grid-template-columns: minmax(300px, .9fr) minmax(420px, 1.25fr);\n  overflow: hidden;\n  border-radius: 18px;\n  box-shadow: 0 18px 55px rgba(52,76,106,.12);\n}\n.tb-newsletter-feature__image {\n  min-height: 420px;\n  background-size: cover !important;\n  background-position: center !important;\n}\n.tb-newsletter-feature__content {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  padding: clamp(44px, 6vw, 72px) !important;\n}\n.tb-newsletter-fields {\n  display: grid !important;\n  grid-template-columns: 1fr 1fr auto;\n  gap: 12px;\n}\n.tb-article-author {\n  padding: clamp(72px, 9vw, 112px) 24px !important;\n  background: #f1e8dc !important;\n}\n.tb-article-author__inner {\n  width: min(1000px, 100%);\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(280px, 380px) 1fr;\n  gap: clamp(42px, 7vw, 82px);\n  align-items: center;\n}\n.tb-article-author__inner > img {\n  width: 100%;\n  height: 500px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 16px;\n  box-shadow: 0 16px 42px rgba(52,76,106,.14);\n}\n.tb-article-author h2 {\n  max-width: 560px;\n  font-size: clamp(36px, 4vw, 54px);\n  line-height: 1.05;\n}\n.tb-article-comments {\n  width: min(820px, calc(100% - 48px));\n  margin: clamp(64px, 8vw, 96px) auto !important;\n  padding: clamp(42px, 6vw, 68px) !important;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.14);\n  border-radius: 18px;\n  box-shadow: 0 14px 42px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments textarea,\n.tb-article-comments input:not([type=\"submit\"]) {\n  width: 100%;\n  box-sizing: border-box;\n}\n.tb-article-navigation {\n  width: min(1040px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: 0 0 clamp(72px, 8vw, 104px);\n}\n@media (max-width: 760px) {\n  .tb-article-header { width: min(100% - 32px, 860px); padding-top: 48px; }\n  .tb-article-hero { padding-left: 16px; padding-right: 16px; }\n  .tb-article-hero .wp-block-post-featured-image img { height: 58vw; min-height: 260px; border-radius: 12px; }\n  .tb-article-body { width: min(100% - 36px, 720px); font-size: 17px; }\n  .tb-article-body .alignwide { width: calc(100vw - 32px); }\n  .tb-newsletter-feature { width: calc(100% - 32px) !important; grid-template-columns: 1fr; }\n  .tb-newsletter-feature__image { min-height: 280px; }\n  .tb-newsletter-fields { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner > img { height: 420px; }\n  .tb-article-comments, .tb-article-navigation { width: calc(100% - 32px); }\n}\n\n/* Editorial depth refinement */\n.tb-article-page {\n  background: linear-gradient(180deg, #e8eef2 0, #fbf8f2 720px) !important;\n}\n.tb-article-header {\n  position: relative;\n  z-index: 1;\n  width: min(1040px, calc(100% - 48px));\n  margin: clamp(46px, 6vw, 78px) auto 0;\n  padding: clamp(48px, 6vw, 76px);\n  text-align: left;\n  background: rgba(255,255,255,.96);\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 22px;\n  box-shadow: 0 22px 60px rgba(52,76,106,.11);\n  box-sizing: border-box;\n}\n.tb-article-title {\n  max-width: 850px;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-article-dek {\n  position: relative;\n  max-width: 800px;\n  margin: 36px 0 26px !important;\n  padding: 58px 34px 30px;\n  background: #dfeaed;\n  border-left: 6px solid #d9a21b;\n  border-radius: 12px;\n  box-sizing: border-box;\n  font-size: clamp(17px, 1.7vw, 21px);\n}\n.tb-article-dek::before {\n  content: \"At a glance\";\n  position: absolute;\n  top: 25px;\n  left: 34px;\n  color: #344c6a;\n  font-family: inherit;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .15em;\n  text-transform: uppercase;\n}\n.tb-article-meta {\n  justify-content: flex-start !important;\n}\n.tb-article-hero {\n  position: relative;\n  z-index: 2;\n  margin-top: -26px;\n}\n.tb-article-body {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(48px, 6vw, 72px);\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.1);\n  border-radius: 20px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments {\n  margin-top: 34px !important;\n  margin-bottom: clamp(64px, 8vw, 96px) !important;\n}\n.tb-newsletter-feature {\n  margin-top: 0 !important;\n}\n@media (max-width: 760px) {\n  .tb-article-header {\n    width: calc(100% - 28px);\n    margin-top: 22px;\n    padding: 34px 24px;\n    border-radius: 15px;\n  }\n  .tb-article-dek {\n    padding: 54px 22px 24px;\n  }\n  .tb-article-dek::before {\n    left: 22px;\n  }\n  .tb-article-hero {\n    margin-top: -14px;\n  }\n  .tb-article-body {\n    width: calc(100% - 28px);\n    padding: 36px 22px;\n    border-radius: 15px;\n  }\n}\n\n/* Blog realtor rail and Tanya-color summary */\n.tb-article-dek {\n  background: #f7f1e7 !important;\n  border-left-color: #d6a3b5 !important;\n  color: #344c6a;\n  box-shadow: inset 0 0 0 1px rgba(52,76,106,.08);\n}\n.tb-article-dek::before { color: #344c6a; }\n.tb-blog-layout {\n  width: min(1120px, calc(100% - 48px));\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(0, 760px) 320px;\n  gap: 42px;\n  align-items: start;\n}\n.tb-blog-main .tb-article-body,\n.tb-blog-main .tb-article-comments {\n  width: 100%;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-blog-main .tb-article-comments { margin-top: 34px !important; }\n.tb-blog-rail {\n  position: sticky;\n  top: 48px;\n  display: grid;\n  gap: 26px;\n}\n.tb-blog-rail__intro,\n.tb-blog-listings {\n  padding: 26px;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 18px;\n  box-shadow: 0 14px 38px rgba(52,76,106,.08);\n}\n.tb-blog-rail__intro > img {\n  display: block;\n  width: 190px;\n  height: 190px;\n  margin: -4px auto 22px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 50% 50% 46% 54%;\n  box-shadow: 12px 12px 0 #f2dce4;\n}\n.tb-blog-rail__eyebrow {\n  margin: 0 0 9px;\n  color: #d093aa;\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: .14em;\n  text-transform: uppercase;\n}\n.tb-blog-rail h2 {\n  margin: 0 0 12px;\n  color: #344c6a;\n  font-size: 30px;\n  line-height: 1.05;\n}\n.tb-blog-rail p { line-height: 1.55; }\n.tb-blog-rail__button {\n  display: inline-block;\n  margin-top: 8px;\n  padding: 12px 16px;\n  color: #fff !important;\n  background: #344c6a;\n  border-radius: 4px;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .08em;\n  text-decoration: none;\n  text-transform: uppercase;\n}\n.tb-listing-grid { display: grid; gap: 18px; margin-top: 20px; }\n.tb-listing-card {\n  display: block;\n  overflow: hidden;\n  color: #25364a !important;\n  background: #fbf8f2;\n  border: 1px solid rgba(52,76,106,.11);\n  border-radius: 12px;\n  text-decoration: none !important;\n  transition: transform .2s ease, box-shadow .2s ease;\n}\n.tb-listing-card:hover {\n  transform: translateY(-3px);\n  box-shadow: 0 12px 26px rgba(52,76,106,.12);\n}\n.tb-listing-card__image {\n  position: relative;\n  display: block;\n  height: 150px;\n}\n.tb-listing-card__image img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n.tb-listing-card__image > span {\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  padding: 6px 9px;\n  color: #344c6a;\n  background: #f7f1e7;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 800;\n  letter-spacing: .1em;\n  text-transform: uppercase;\n}\n.tb-listing-card__body { display: grid; gap: 3px; padding: 15px; }\n.tb-listing-card__body strong { font-family: inherit; font-size: 15px; }\n.tb-listing-card__body b { margin-top: 6px; color: #344c6a; font-size: 18px; }\n.tb-listing-card__body small { color: #6b7580; font-size: 12px; }\n.tb-listing-fallback {\n  display: none;\n  margin-top: 18px;\n  padding: 20px;\n  background: #f7f1e7;\n  border-radius: 12px;\n}\n.tb-listing-grid:not(:has(.tb-listing-card)) + .tb-listing-fallback { display: block; }\n.tb-listing-fallback h3 { margin-top: 0; color: #344c6a; }\n.tb-listing-fallback a,\n.tb-blog-rail__text-link {\n  display: block;\n  margin-top: 12px;\n  color: #344c6a !important;\n  font-weight: 700;\n}\n.tb-blog-rail__text-link { font-size: 13px; }\n@media (max-width: 1020px) {\n  .tb-blog-layout { grid-template-columns: 1fr; }\n  .tb-blog-rail { position: static; grid-template-columns: .8fr 1.2fr; }\n  .tb-listing-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }\n}\n@media (max-width: 700px) {\n  .tb-blog-layout { width: calc(100% - 28px); }\n  .tb-blog-rail { grid-template-columns: 1fr; }\n  .tb-listing-grid { grid-template-columns: 1fr; }\n}\n.tb-article-page{display:grid;grid-template-columns:minmax(0,760px) 320px;column-gap:42px;justify-content:center;} .tb-article-header{grid-column:1 / -1;grid-row:1;} .tb-article-hero{grid-column:1 / -1;grid-row:2;} .tb-article-body{grid-column:1;grid-row:3;width:100%;margin-left:0;margin-right:0;} .tb-blog-rail{grid-column:2;grid-row:3 / span 2;} .tb-article-comments{grid-column:1;grid-row:4;width:100%;margin-left:0!important;margin-right:0!important;} .tb-newsletter-feature{grid-column:1 / -1;grid-row:5;} .tb-article-navigation{grid-column:1 / -1;grid-row:6;} @media(max-width:1020px){.tb-article-page{display:block}.tb-blog-rail{position:static;width:min(860px,calc(100% - 28px));margin:34px auto 72px}.tb-article-body,.tb-article-comments{width:min(860px,calc(100% - 28px));margin-left:auto!important;margin-right:auto!important}.tb-blog-rail{display:grid;grid-template-columns:.8fr 1.2fr}.tb-listing-grid{grid-template-columns:repeat(2,minmax(0,1fr))}} @media(max-width:700px){.tb-blog-rail{grid-template-columns:1fr}.tb-listing-grid{grid-template-columns:1fr}}\n.tb-blog-rail{align-self:start;height:max-content;}\n</style>\n<!-- /wp:html --> <!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-article-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-article-page\">\n\n	<!-- wp:group {\"className\":\"tb-article-header\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"920px\"}} -->\n	<header class=\"wp-block-group tb-article-header\">\n		<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-label\"} /-->\n		<!-- wp:post-title {\"level\":1,\"className\":\"tb-article-title\",\"fontSize\":\"x-large\"} /-->\n		<!-- wp:post-excerpt {\"moreText\":\"\",\"excerptLength\":32,\"className\":\"tb-article-dek\"} /-->\n		<!-- wp:group {\"className\":\"tb-article-meta\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\"}} -->\n		<div class=\"wp-block-group tb-article-meta\">\n			<!-- wp:paragraph --><p>From Tanya Barrans</p><!-- /wp:paragraph -->\n			<!-- wp:post-date /-->\n		</div>\n		<!-- /wp:group -->\n	</header>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-hero\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-hero\">\n		<!-- wp:post-featured-image {\"aspectRatio\":\"16/9\",\"sizeSlug\":\"full\"} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-body\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-body\">\n		<!-- wp:post-content {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-comments\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\"}} -->\n<div class=\"wp-block-group tb-article-comments\">\n<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Join the conversation</h2><!-- /wp:heading -->\n<!-- wp:paragraph --><p>Have a tip, a question, or a story of your own? I’d love to hear it.</p><!-- /wp:paragraph -->\n<!-- wp:comments -->\n<div class=\"wp-block-comments\">\n<!-- wp:comments-title {\"showPostTitle\":false} /-->\n<!-- wp:comment-template -->\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} --><div class=\"wp-block-group\"><!-- wp:avatar {\"size\":48} /--><!-- wp:group --><div class=\"wp-block-group\"><!-- wp:comment-author-name /--><!-- wp:comment-date /--></div><!-- /wp:group --></div><!-- /wp:group -->\n<!-- wp:comment-content /-->\n<!-- wp:comment-reply-link /-->\n<!-- /wp:comment-template -->\n<!-- wp:post-comments-form /-->\n</div>\n<!-- /wp:comments -->\n</div>\n<!-- /wp:group --> <!-- wp:html -->\n<aside class=\"tb-blog-rail\" aria-label=\"About Tanya and current listings\">\n  <section class=\"tb-blog-rail__intro\">\n    <img src=\"/wp-content/uploads/2026/07/about-main.jpg\" alt=\"Tanya Barrans, Puget Sound real estate broker\" loading=\"lazy\">\n    <p class=\"tb-blog-rail__eyebrow\">Your local real estate resource</p>\n    <h2>Hi, I’m Tanya.</h2>\n    <p>I help buyers and sellers make thoughtful moves across Renton and the South Sound—with honest guidance and a little more personality.</p>\n    <a class=\"tb-blog-rail__button\" href=\"/contact/\">Ask Tanya a question</a>\n  </section>\n  <section class=\"tb-blog-listings\">\n    <p class=\"tb-blog-rail__eyebrow\">Currently listed by Tanya</p>\n    <h2>Homes worth a look</h2>\n    <div class=\"tb-listing-grid\">\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/olympia/5246-yearley-drive-ne-/21476453\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/253/429/2534297.jpg\" alt=\"5246 Yearley Drive NE in Olympia\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>5246 Yearley Drive NE</strong><small>Olympia, WA</small><b>$389,999</b><small>2 beds · 1.75 baths · 972 sq ft</small></span>\n      </a>\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/puyallup/18026-75th-avenue-e-/21497093\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584.jpg\" alt=\"18026 75th Avenue E in Puyallup\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>18026 75th Avenue E</strong><small>Puyallup, WA</small><b>$545,000</b><small>4 beds · 2.5 baths · 2,201 sq ft</small></span>\n      </a>\n    </div>\n    <div class=\"tb-listing-fallback\">\n      <h3>Nothing active right now—but the search doesn’t stop here.</h3>\n      <p>Browse homes on my John L. Scott site or tell me what you’re hoping to find.</p>\n      <a href=\"https://tanyab.johnlscott.com/search\" target=\"_blank\" rel=\"noopener\">Explore available homes</a>\n      <a href=\"/contact/\">Tell me what you’re looking for</a>\n    </div>\n    <a class=\"tb-blog-rail__text-link\" href=\"https://tanyab.johnlscott.com\" target=\"_blank\" rel=\"noopener\">See all listings on John L. Scott →</a>\n  </section>\n</aside>\n<!-- /wp:html --> <!-- wp:group {\"align\":\"full\",\"className\":\"tb-newsletter-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/newsletter\",\"name\":\"Newsletter Signup\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-newsletter-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg)\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__content tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\"} -->\n		<p class=\"tb-script-accent\">Let’s stay in touch</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Notes worth opening.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Useful home ideas, local stories, and honest real estate guidance—delivered with no pressure and no polished filler.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:html -->\n		<form class=\"tb-newsletter-form\" novalidate>\n			<div class=\"tb-newsletter-fields\">\n				<label class=\"tb-sr-only\" for=\"tb-nl-name\">First name</label>\n				<input type=\"text\" id=\"tb-nl-name\" name=\"name\" class=\"tb-newsletter-input\" placeholder=\"First name\" autocomplete=\"given-name\" />\n\n				<label class=\"tb-sr-only\" for=\"tb-nl-email\">Email address</label>\n				<input type=\"email\" id=\"tb-nl-email\" name=\"email\" class=\"tb-newsletter-input\" placeholder=\"Email address\" autocomplete=\"email\" required />\n\n				<div class=\"tb-newsletter-hp\" aria-hidden=\"true\">\n					<label for=\"tb-nl-website\">Website</label>\n					<input type=\"text\" id=\"tb-nl-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" />\n				</div>\n\n				<button type=\"submit\" class=\"tb-newsletter-submit\">Subscribe</button>\n			</div>\n			<p class=\"tb-newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n		</form>\n		<!-- /wp:html -->\n\n		<!-- wp:paragraph {\"className\":\"tb-newsletter-feature__privacy\"} -->\n		<p class=\"tb-newsletter-feature__privacy\">No spam. Unsubscribe whenever you like.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-navigation\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<nav class=\"wp-block-group tb-article-navigation\" aria-label=\"Article navigation\">\n		<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"}} -->\n		<div class=\"wp-block-group\">\n			<!-- wp:post-navigation-link {\"type\":\"previous\",\"label\":\"Previous story\",\"showTitle\":true,\"linkLabel\":true} /-->\n			<!-- wp:post-navigation-link {\"type\":\"next\",\"label\":\"Next story\",\"showTitle\":true,\"linkLabel\":true} /-->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-journal-back-link\"} --><p class=\"has-text-align-center tb-journal-back-link\"><a href=\"/blog/\">Back to the Journal</a></p><!-- /wp:paragraph -->\n	</nav>\n	<!-- /wp:group -->\n\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'Blog Posts', 'Displays a single post on your website unless a custom template has been applied to that post or a dedicated template exists.', 'publish', 'closed', 'closed', '', 'single', '', '', '2026-08-17 23:37:40', '2026-08-17 23:37:40', '', 0, 'https://violet-wren-104886.hostingersite.com/single/', 0, 'wp_template', '', 0),
(100, 1, '2026-08-14 22:28:19', '2026-08-14 22:28:19', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-journal-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-journal-page\">\n\n	<!-- wp:html -->\n	<section class=\"tb-journal-hero\" aria-labelledby=\"journal-title\">\n		<img class=\"tb-journal-hero__image\" src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-hero.jpg\" alt=\"Warm, sunlit kitchen with natural greenery, flowers, and a welcoming place to gather\" width=\"2400\" height=\"1200\" fetchpriority=\"high\">\n		<div class=\"tb-journal-hero__panel\">\n			<p class=\"tb-page-kicker\">Home, garden, real estate, food, and everyday life</p>\n			<h1 id=\"journal-title\">The Journal</h1>\n			<p>The blog for practical ideas, useful guidance, and inspiration for the way you live.</p>\n		</div>\n	</section>\n	<nav class=\"tb-journal-topics\" aria-label=\"Journal topics\">\n		<div class=\"tb-page-shell\">\n			<a href=\"/category/home-garden/\">Home &amp; Garden</a>\n			<a href=\"/category/home-buying-tips/\">Real Estate</a>\n			<a href=\"/category/rooted-in-renton/\">Rooted in Renton</a>\n		</div>\n	</nav>\n	<!-- /wp:html -->\n\n	<!-- wp:group {\"className\":\"tb-journal-content\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-journal-content\">\n\n		<!-- wp:query {\"queryId\":40,\"query\":{\"perPage\":1,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"\",\"inherit\":false},\"className\":\"tb-journal-feature-query\"} -->\n		<div class=\"wp-block-query tb-journal-feature-query\">\n			<!-- wp:post-template -->\n				<!-- wp:group {\"className\":\"tb-journal-feature\",\"layout\":{\"type\":\"default\"}} -->\n				<div class=\"wp-block-group tb-journal-feature\">\n					<!-- wp:group {\"className\":\"tb-journal-feature__media\",\"layout\":{\"type\":\"default\"}} -->\n					<div class=\"wp-block-group tb-journal-feature__media\">\n						<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"4/3\",\"sizeSlug\":\"large\"} /-->\n					</div>\n					<!-- /wp:group -->\n					<!-- wp:group {\"className\":\"tb-journal-feature__content\",\"layout\":{\"type\":\"constrained\"}} -->\n					<div class=\"wp-block-group tb-journal-feature__content\">\n						<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-label\"} /-->\n						<!-- wp:post-title {\"isLink\":true,\"level\":2} /-->\n						<!-- wp:post-excerpt {\"moreText\":\"Read more →\",\"excerptLength\":30,\"className\":\"tb-journal-feature__excerpt\"} /-->\n						<!-- wp:post-date {\"className\":\"tb-journal-date\"} /-->\n					</div>\n					<!-- /wp:group -->\n				</div>\n				<!-- /wp:group -->\n			<!-- /wp:post-template -->\n		</div>\n		<!-- /wp:query -->\n\n		<!-- wp:group {\"className\":\"tb-journal-story-section\",\"layout\":{\"type\":\"default\"}} -->\n		<section class=\"wp-block-group tb-journal-story-section\" aria-labelledby=\"journal-start-title\">\n			<!-- wp:html --><div class=\"tb-editorial-heading\"><span></span><h2 id=\"journal-start-title\">Start Here</h2><span></span></div><!-- /wp:html -->\n			<!-- wp:query {\"queryId\":41,\"query\":{\"perPage\":3,\"pages\":0,\"offset\":1,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"\",\"inherit\":false},\"className\":\"tb-journal-card-query\"} -->\n			<div class=\"wp-block-query tb-journal-card-query\">\n				<!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n					<!-- wp:group {\"className\":\"tb-journal-card-new\",\"layout\":{\"type\":\"constrained\"}} -->\n					<article class=\"wp-block-group tb-journal-card-new\">\n						<!-- wp:group {\"className\":\"tb-journal-card-new__media\",\"layout\":{\"type\":\"default\"}} -->\n						<div class=\"wp-block-group tb-journal-card-new__media\"><!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"4/3\",\"sizeSlug\":\"medium_large\"} /--></div>\n						<!-- /wp:group -->\n						<!-- wp:group {\"className\":\"tb-journal-card-new__content\",\"layout\":{\"type\":\"constrained\"}} -->\n						<div class=\"wp-block-group tb-journal-card-new__content\">\n							<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-label\"} /-->\n							<!-- wp:post-title {\"isLink\":true,\"level\":3} /-->\n							<!-- wp:post-excerpt {\"moreText\":\"Read more →\",\"excerptLength\":18,\"className\":\"tb-journal-card-new__excerpt\"} /-->\n						</div>\n						<!-- /wp:group -->\n					</article>\n					<!-- /wp:group -->\n				<!-- /wp:post-template -->\n			</div>\n			<!-- /wp:query -->\n		</section>\n		<!-- /wp:group -->\n\n		<!-- wp:group {\"className\":\"tb-journal-story-section tb-journal-latest-section\",\"layout\":{\"type\":\"default\"}} -->\n		<section class=\"wp-block-group tb-journal-story-section tb-journal-latest-section\" aria-labelledby=\"journal-latest-title\">\n			<!-- wp:html --><div class=\"tb-editorial-heading\"><span></span><h2 id=\"journal-latest-title\">Latest Guides</h2><span></span></div><!-- /wp:html -->\n			<!-- wp:query {\"queryId\":42,\"query\":{\"perPage\":6,\"pages\":0,\"offset\":4,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"\",\"inherit\":false},\"className\":\"tb-journal-card-query\"} -->\n			<div class=\"wp-block-query tb-journal-card-query\">\n				<!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n					<!-- wp:group {\"className\":\"tb-journal-card-new tb-journal-card-new\\u002d\\u002dcompact\",\"layout\":{\"type\":\"constrained\"}} -->\n					<article class=\"wp-block-group tb-journal-card-new tb-journal-card-new--compact\">\n						<!-- wp:group {\"className\":\"tb-journal-card-new__media\",\"layout\":{\"type\":\"default\"}} -->\n						<div class=\"wp-block-group tb-journal-card-new__media\"><!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"3/2\",\"sizeSlug\":\"medium_large\"} /--></div>\n						<!-- /wp:group -->\n						<!-- wp:group {\"className\":\"tb-journal-card-new__content\",\"layout\":{\"type\":\"constrained\"}} -->\n						<div class=\"wp-block-group tb-journal-card-new__content\">\n							<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-label\"} /-->\n							<!-- wp:post-title {\"isLink\":true,\"level\":3} /-->\n							<!-- wp:paragraph {\"className\":\"tb-journal-read-link\"} --><p class=\"tb-journal-read-link\">Read more →</p><!-- /wp:paragraph -->\n						</div>\n						<!-- /wp:group -->\n					</article>\n					<!-- /wp:group -->\n				<!-- /wp:post-template -->\n				<!-- wp:query-no-results --><!-- wp:paragraph {\"className\":\"tb-query-empty\"} --><p class=\"tb-query-empty\">More guides are on the way.</p><!-- /wp:paragraph --><!-- /wp:query-no-results -->\n			</div>\n			<!-- /wp:query -->\n		</section>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-newsletter-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/newsletter\",\"name\":\"Newsletter Signup\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-newsletter-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg)\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__content tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\"} -->\n		<p class=\"tb-script-accent\">Let’s stay in touch</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Notes worth opening.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Useful home ideas, local stories, and honest real estate guidance—delivered with no pressure and no polished filler.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:html -->\n		<form class=\"tb-newsletter-form\" novalidate>\n			<div class=\"tb-newsletter-fields\">\n				<label class=\"tb-sr-only\" for=\"tb-nl-name\">First name</label>\n				<input type=\"text\" id=\"tb-nl-name\" name=\"name\" class=\"tb-newsletter-input\" placeholder=\"First name\" autocomplete=\"given-name\" />\n\n				<label class=\"tb-sr-only\" for=\"tb-nl-email\">Email address</label>\n				<input type=\"email\" id=\"tb-nl-email\" name=\"email\" class=\"tb-newsletter-input\" placeholder=\"Email address\" autocomplete=\"email\" required />\n\n				<div class=\"tb-newsletter-hp\" aria-hidden=\"true\">\n					<label for=\"tb-nl-website\">Website</label>\n					<input type=\"text\" id=\"tb-nl-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" />\n				</div>\n\n				<button type=\"submit\" class=\"tb-newsletter-submit\">Subscribe</button>\n			</div>\n			<p class=\"tb-newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n		</form>\n		<!-- /wp:html -->\n\n		<!-- wp:paragraph {\"className\":\"tb-newsletter-feature__privacy\"} -->\n		<p class=\"tb-newsletter-feature__privacy\">No spam. Unsubscribe whenever you like.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n	<!-- wp:html -->\n	<section class=\"tb-journal-tanya-cta\" aria-labelledby=\"journal-tanya-title\">\n		<div class=\"tb-page-shell tb-journal-tanya-cta__inner\">\n			<img src=\"/wp-content/uploads/2026/07/contact-circle.jpg\" alt=\"Tanya Barrans\" width=\"700\" height=\"700\" loading=\"lazy\">\n			<div>\n				<p class=\"tb-page-kicker\">A thoughtful next step</p>\n				<h2 id=\"journal-tanya-title\">Let&rsquo;s talk about your next chapter.</h2>\n				<p>Whether you are buying, selling, or simply exploring your options, Tanya is here to help you love where you live.</p>\n			</div>\n			<a class=\"tb-page-button tb-page-button--light\" href=\"https://calendar.app.google/zndHShd1Rm6W6Qb38\" target=\"_blank\" rel=\"noopener noreferrer\">Meet With Tanya</a>\n		</div>\n	</section>\n	<!-- /wp:html -->\n\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'Blog Home', 'Displays the latest posts as either the site homepage or as the \"Posts page\" as defined under reading settings. If it exists, the Front Page template overrides this template when posts are shown on the homepage.', 'publish', 'closed', 'closed', '', 'home', '', '', '2026-08-14 22:28:19', '2026-08-14 22:28:19', '', 0, 'https://violet-wren-104886.hostingersite.com/home/', 0, 'wp_template', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(101, 1, '2026-08-14 22:29:19', '2026-08-14 22:29:19', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<main class=\"wp-block-group\">\n	<!-- Section order follows the Homepage Blueprint, with one deliberate\n	     departure: Meet Tanya sits directly under the hero at Mike\'s request,\n	     rather than at the blueprint\'s position seven. Everything else keeps\n	     the blueprint sequence. -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-home-hero\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/hero\",\"name\":\"Homepage Hero\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-home-hero has-alabaster-background-color has-background\">\n\n	<!-- wp:html -->\n	<img\n		class=\"tb-home-hero__image\"\n		src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-hero.jpg\"\n		alt=\"\"\n		width=\"1720\"\n		height=\"914\"\n		fetchpriority=\"high\"\n		decoding=\"async\"\n	/>\n	<!-- /wp:html -->\n\n	<!-- wp:group {\"className\":\"tb-home-hero__inner\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-home-hero__inner\">\n\n		<!-- wp:group {\"className\":\"tb-home-hero__content tb-hero-arrive\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-home-hero__content tb-hero-arrive\">\n\n			<!-- The blueprint headline is a full sentence and the page may only\n			     carry one H1, so the script accent lives inside the heading\n			     rather than as a separate line above it. -->\n			<!-- wp:heading {\"level\":1,\"className\":\"tb-home-hero__title\"} -->\n			<h1 class=\"wp-block-heading tb-home-hero__title\"><span class=\"tb-script-accent\" style=\"text-transform:none\">Helping you</span> love your home<br>and where you live.</h1>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"tb-home-hero__dek\"} -->\n			<p class=\"tb-home-hero__dek\">Serving buyers and sellers in Renton and throughout the Puget Sound region.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:buttons {\"className\":\"tb-home-hero__buttons\",\"style\":{\"spacing\":{\"blockGap\":\"0.75rem\",\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n			<div class=\"wp-block-buttons tb-home-hero__buttons\" style=\"margin-top:var(--wp--preset--spacing--40)\">\n				<!-- wp:button {\"backgroundColor\":\"charcoal\"} -->\n				<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-charcoal-background-color has-background wp-element-button\" href=\"/contact/\">Let’s Talk About Your Next Move</a></div>\n				<!-- /wp:button -->\n\n								<!-- wp:button {\"backgroundColor\":\"coral\",\"textColor\":\"charcoal\"} -->\n				<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-charcoal-color has-coral-background-color has-text-color has-background wp-element-button\" href=\"/renton/\">Explore Renton</a></div>\n				<!-- /wp:button -->\n			</div>\n			<!-- /wp:buttons -->\n\n		</div>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-editorial-feature tb-editorial-feature\\u002d\\u002dphoto-left tb-about-feature\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/about-intro\",\"name\":\"About Intro\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-editorial-feature tb-editorial-feature--photo-left tb-about-feature has-alabaster-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-editorial-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-editorial-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/uploads/2026/07/about-main.jpg);background-position:center 20%\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-editorial-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-editorial-feature__content tb-reveal\">\n\n		<!-- wp:paragraph {\"className\":\"tb-eyebrow\",\"textColor\":\"dusty-blush\"} -->\n		<p class=\"tb-eyebrow has-dusty-blush-color has-text-color\">Meet Tanya</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"xx-large\"} -->\n		<h2 class=\"wp-block-heading has-xx-large-font-size\">Real estate is personal.<br><em>Your guidance should be, too.</em></h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Buying or selling a home is exciting, stressful, emotional, and sometimes downright overwhelming. Tanya’s goal is to make sure you never feel like you are navigating it alone.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">You will get honest advice, quick answers, plenty of laughs, and someone who genuinely cares about the outcome—not just the closing date.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n		<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--40)\">\n			<!-- wp:button {\"backgroundColor\":\"charcoal\",\"textColor\":\"base\"} -->\n			<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-base-color has-charcoal-background-color has-text-color has-background wp-element-button\" href=\"/about/\">Meet Tanya</a></div>\n			<!-- /wp:button -->\n		</div>\n		<!-- /wp:buttons -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-ways\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1320px\"},\"metadata\":{\"patternName\":\"tanya-barrans/pathways\",\"name\":\"Three Ways Tanya Helps\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-ways has-alabaster-background-color has-background\">\n\n	<!-- wp:heading {\"level\":2,\"textAlign\":\"center\",\"className\":\"tb-ways__title\"} -->\n	<h2 class=\"wp-block-heading has-text-align-center tb-ways__title\">Three ways Tanya helps</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:group {\"align\":\"wide\",\"className\":\"tb-ways__grid\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group alignwide tb-ways__grid\">\n\n		<!-- wp:group {\"className\":\"tb-way tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-way tb-reveal\">\n			<!-- wp:html -->\n			<img class=\"tb-way__photo\" src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-front-door.jpg\" alt=\"\" width=\"900\" height=\"1125\" loading=\"lazy\" decoding=\"async\" />\n			<!-- /wp:html -->\n			<!-- wp:heading {\"level\":3,\"className\":\"tb-way__title\"} -->\n			<h3 class=\"wp-block-heading tb-way__title\">Buy With Confidence</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"tb-way__copy\"} -->\n			<p class=\"tb-way__copy\">Find the right home, neighborhood, and long-term fit.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-way__link\"} -->\n			<p class=\"tb-way__link\"><a href=\"/buy/\">Start Your Home Search <span aria-hidden=\"true\">&rarr;</span></a></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:group {\"className\":\"tb-way tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-way tb-reveal\">\n			<!-- wp:html -->\n			<img class=\"tb-way__photo\" src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg\" alt=\"\" width=\"900\" height=\"1125\" loading=\"lazy\" decoding=\"async\" />\n			<!-- /wp:html -->\n			<!-- wp:heading {\"level\":3,\"className\":\"tb-way__title\"} -->\n			<h3 class=\"wp-block-heading tb-way__title\">Sell With Strategy</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"tb-way__copy\"} -->\n			<p class=\"tb-way__copy\">Clear pricing, thoughtful preparation, and marketing built to make your home stand out.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-way__link\"} -->\n			<p class=\"tb-way__link\"><a href=\"/sell/\">Explore My Selling Plan <span aria-hidden=\"true\">&rarr;</span></a></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:group {\"className\":\"tb-way tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-way tb-reveal\">\n			<!-- wp:html -->\n			<img class=\"tb-way__photo\" src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-kitchen-garden.jpg\" alt=\"\" width=\"900\" height=\"1125\" loading=\"lazy\" decoding=\"async\" />\n			<!-- /wp:html -->\n			<!-- wp:heading {\"level\":3,\"className\":\"tb-way__title\"} -->\n			<h3 class=\"wp-block-heading tb-way__title\">Love Where You Live Now</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"tb-way__copy\"} -->\n			<p class=\"tb-way__copy\">Home projects, garden ideas, local guides, and practical homeowner resources.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-way__link\"} -->\n			<p class=\"tb-way__link\"><a href=\"/blog/\">Browse the Journal <span aria-hidden=\"true\">&rarr;</span></a></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-editorial-feature tb-editorial-feature\\u002d\\u002dphoto-right tb-real-estate-feature\",\"backgroundColor\":\"sand\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/listings-placeholder\",\"name\":\"Real Estate Guidance\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-editorial-feature tb-editorial-feature--photo-right tb-real-estate-feature has-sand-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-editorial-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-editorial-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-front-door.jpg);background-position:center\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-editorial-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-editorial-feature__content tb-reveal\">\n\n		<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n		<p class=\"tb-eyebrow\">Real Estate</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"xx-large\"} -->\n		<h2 class=\"wp-block-heading has-xx-large-font-size\">Your next move should feel <em>clear.</em></h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Whether you are buying your first home, selling a place filled with memories, or simply wondering whether now is the right time, you deserve a strategy built around your goals—not a one-size-fits-all plan.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:group {\"className\":\"tb-real-estate-links\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n		<div class=\"wp-block-group tb-real-estate-links\">\n			<!-- wp:paragraph -->\n			<p><a href=\"/buy/\">Buying a Home <span aria-hidden=\"true\">→</span></a></p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p><a href=\"/sell/\">Selling a Home <span aria-hidden=\"true\">→</span></a></p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p><a href=\"/listings/\">View Listings <span aria-hidden=\"true\">→</span></a></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-brand-pillars\",\"backgroundColor\":\"charcoal\",\"textColor\":\"base\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"},\"metadata\":{\"patternName\":\"tanya-barrans/credibility\",\"name\":\"Brand Promise\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-brand-pillars has-base-color has-charcoal-background-color has-text-color has-background\">\n\n	<!-- wp:heading {\"level\":2,\"className\":\"tb-sr-only\"} -->\n	<h2 class=\"wp-block-heading tb-sr-only\">What you can expect from Tanya</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:columns {\"align\":\"wide\",\"className\":\"tb-brand-pillars__grid\"} -->\n	<div class=\"wp-block-columns alignwide tb-brand-pillars__grid\">\n\n		<!-- wp:column {\"className\":\"tb-brand-pillar tb-reveal\"} -->\n		<div class=\"wp-block-column tb-brand-pillar tb-reveal\">\n			<!-- wp:paragraph {\"className\":\"tb-brand-pillar__label\"} -->\n			<p class=\"tb-brand-pillar__label\">Clear Advice</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p>Practical answers that help you make a decision you will still feel good about years from now.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-brand-pillar tb-reveal\"} -->\n		<div class=\"wp-block-column tb-brand-pillar tb-reveal\">\n			<!-- wp:paragraph {\"className\":\"tb-brand-pillar__label\"} -->\n			<p class=\"tb-brand-pillar__label\">Local Knowledge</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p>Neighborhood context, market perspective, and the everyday details that shape where you live.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-brand-pillar tb-reveal\"} -->\n		<div class=\"wp-block-column tb-brand-pillar tb-reveal\">\n			<!-- wp:paragraph {\"className\":\"tb-brand-pillar__label\"} -->\n			<p class=\"tb-brand-pillar__label\">Real Relationships</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p>Responsive, honest guidance built around your family, your goals, and what matters after closing.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n	</div>\n	<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-story-quote\",\"backgroundColor\":\"coral\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull tb-story-quote has-coral-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-story-quote__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-story-quote__content tb-reveal\">\n\n		<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n		<p class=\"tb-eyebrow\">What Clients Remember</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"className\":\"tb-story-quote__mark\"} -->\n		<p class=\"tb-story-quote__mark\" aria-hidden=\"true\">“</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:quote {\"className\":\"tb-story-quote__quote\"} -->\n		<blockquote class=\"wp-block-quote tb-story-quote__quote\"><p>By the end, you felt like family.</p></blockquote>\n		<!-- /wp:quote -->\n\n				<!-- wp:paragraph {\"textColor\":\"charcoal\"} -->\n		<p class=\"has-charcoal-color has-text-color\">“Tanya did an amazing job selling our home. She made sure it was picture ready for getting the maximum possible price for the market. When we ran into snags she went above and beyond to fix them for us. She was available for any questions or concerns we may have had. When it came time to negotiate, she got the best price for us.”</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"className\":\"tb-story-quote__attribution\",\"textColor\":\"charcoal\",\"fontSize\":\"small\"} -->\n		<p class=\"tb-story-quote__attribution has-charcoal-color has-text-color has-small-font-size\">Christian Herzberger · Google review</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"className\":\"tb-text-link\"} -->\n		<p class=\"tb-text-link\"><a href=\"https://g.page/r/CTDpOcL-7SDkEAE\" target=\"_blank\" rel=\"noopener noreferrer\">Read Tanya’s Google reviews <span aria-hidden=\"true\">→</span></a></p>\n		<!-- /wp:paragraph -->\n\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-story-quote__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-story-quote__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg)\"></div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"tb-quote-row-section\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull tb-quote-row-section has-alabaster-background-color has-background\">\n	<div class=\"tb-page-shell\">\n		<div class=\"tb-quote-row\">\n\n			<figure class=\"tb-quote-card tb-reveal\">\n				<blockquote>\n					<p>“Tanya was patient with me as I searched for my first home in a market that seemed impossible for a single mom. She was motivated and encouraging when I wanted to give up. And now, I own my own home!”</p>\n				</blockquote>\n				<figcaption>Margo Hooper <span>Google review</span></figcaption>\n			</figure>\n\n			<figure class=\"tb-quote-card tb-reveal\">\n				<blockquote>\n					<p>“…After working with a different agent for four months with no success, we decided to reach out to Tanya. We asked her to help us find a house. We gave her only a week. She helped us find the perfect house in the right neighborhood in 4 days!”</p>\n				</blockquote>\n				<figcaption>Bernice Manriquez <span>Google review</span></figcaption>\n			</figure>\n\n		</div>\n	</div>\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-journal-section\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"},\"metadata\":{\"patternName\":\"tanya-barrans/blog-teaser\",\"name\":\"Latest From the Journal\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-journal-section has-alabaster-background-color has-background\">\n\n	<!-- wp:group {\"align\":\"wide\",\"className\":\"tb-journal-section__header\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\",\"verticalAlignment\":\"bottom\"}} -->\n	<div class=\"wp-block-group alignwide tb-journal-section__header\">\n		<!-- wp:group {\"className\":\"tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-reveal\">\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">The Journal</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:heading {\"fontSize\":\"xx-large\"} -->\n			<h2 class=\"wp-block-heading has-xx-large-font-size\">Latest from the Journal</h2>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n			<p class=\"has-graphite-color has-text-color\">The Journal is the blog: practical ideas for real estate, decorating, gardening, food, homeownership, and everyday life. Rooted in Renton is reserved for local stories and neighborhood guides.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:paragraph {\"className\":\"tb-text-link\"} -->\n		<p class=\"tb-text-link\"><a href=\"/blog/\">Explore the Journal <span aria-hidden=\"true\">→</span></a></p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:query {\"queryId\":1,\"query\":{\"perPage\":3,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\"},\"align\":\"wide\",\"className\":\"tb-journal-query\"} -->\n	<div class=\"wp-block-query alignwide tb-journal-query\">\n		<!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n\n			<!-- wp:group {\"className\":\"tb-journal-card tb-reveal\",\"layout\":{\"type\":\"constrained\"}} -->\n			<div class=\"wp-block-group tb-journal-card\">\n				<!-- wp:post-featured-image {\"aspectRatio\":\"4/3\",\"isLink\":true} /-->\n				<!-- wp:group {\"className\":\"tb-journal-card__content\",\"layout\":{\"type\":\"constrained\"}} -->\n				<div class=\"wp-block-group tb-journal-card__content\">\n					<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-card__category\"} /-->\n					<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"large\"} /-->\n					<!-- wp:post-date {\"textColor\":\"graphite\",\"fontSize\":\"small\"} /-->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:group -->\n\n		<!-- /wp:post-template -->\n	</div>\n	<!-- /wp:query -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-newsletter-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/newsletter\",\"name\":\"Newsletter Signup\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-newsletter-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg)\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__content tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\"} -->\n		<p class=\"tb-script-accent\">Let’s stay in touch</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Notes worth opening.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Useful home ideas, local stories, and honest real estate guidance—delivered with no pressure and no polished filler.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:html -->\n		<form class=\"tb-newsletter-form\" novalidate>\n			<div class=\"tb-newsletter-fields\">\n				<label class=\"tb-sr-only\" for=\"tb-nl-name\">First name</label>\n				<input type=\"text\" id=\"tb-nl-name\" name=\"name\" class=\"tb-newsletter-input\" placeholder=\"First name\" autocomplete=\"given-name\" />\n\n				<label class=\"tb-sr-only\" for=\"tb-nl-email\">Email address</label>\n				<input type=\"email\" id=\"tb-nl-email\" name=\"email\" class=\"tb-newsletter-input\" placeholder=\"Email address\" autocomplete=\"email\" required />\n\n				<div class=\"tb-newsletter-hp\" aria-hidden=\"true\">\n					<label for=\"tb-nl-website\">Website</label>\n					<input type=\"text\" id=\"tb-nl-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" />\n				</div>\n\n				<button type=\"submit\" class=\"tb-newsletter-submit\">Subscribe</button>\n			</div>\n			<p class=\"tb-newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n		</form>\n		<!-- /wp:html -->\n\n		<!-- wp:paragraph {\"className\":\"tb-newsletter-feature__privacy\"} -->\n		<p class=\"tb-newsletter-feature__privacy\">No spam. Unsubscribe whenever you like.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-closing-cta\",\"backgroundColor\":\"charcoal\",\"textColor\":\"base\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"920px\"},\"metadata\":{\"patternName\":\"tanya-barrans/cta\",\"name\":\"Contact CTA Band\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-closing-cta has-base-color has-charcoal-background-color has-text-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-closing-cta__inner tb-reveal\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"760px\"}} -->\n	<div class=\"wp-block-group tb-closing-cta__inner tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\"} -->\n		<p class=\"tb-script-accent\">When you’re ready</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"xx-large\",\"textColor\":\"base\"} -->\n		<h2 class=\"wp-block-heading has-text-align-center has-base-color has-text-color has-xx-large-font-size\">Your next move should support the life you want to live.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"stone\"} -->\n		<p class=\"has-text-align-center has-stone-color has-text-color\">Whether you are three years or three weeks from a move, Tanya will give you an honest look at your options—without pressure.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"flexWrap\":\"wrap\"},\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n		<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--40)\">\n			<!-- wp:button {\"backgroundColor\":\"coral\",\"textColor\":\"charcoal\"} -->\n			<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-charcoal-color has-coral-background-color has-text-color has-background wp-element-button\" href=\"/contact/\">Tell Me What You’re Planning</a></div>\n			<!-- /wp:button -->\n			<!-- wp:button {\"className\":\"tb-button-outline tb-button-outline\\u002d\\u002dlight\",\"textColor\":\"base\"} -->\n			<div class=\"wp-block-button tb-button-outline tb-button-outline--light\"><a class=\"wp-block-button__link has-base-color has-text-color wp-element-button\" href=\"https://calendar.app.google/zndHShd1Rm6W6Qb38\" target=\"_blank\" rel=\"noopener noreferrer\">Schedule a Conversation</a></div>\n			<!-- /wp:button -->\n		</div>\n		<!-- /wp:buttons -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'Front Page', 'Displays your site\'s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.', 'inherit', 'closed', 'closed', '', '95-revision-v1', '', '', '2026-08-14 22:29:19', '2026-08-14 22:29:19', '', 95, 'https://violet-wren-104886.hostingersite.com/?p=101', 0, 'revision', '', 0),
(102, 1, '2026-08-14 22:29:56', '2026-08-14 22:29:56', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<main class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--40)\">\n\n	<!-- wp:query-title {\"type\":\"archive\",\"showPrefix\":false,\"textAlign\":\"center\",\"fontSize\":\"x-large\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}}} /-->\n\n	<!-- wp:query {\"queryId\":20,\"query\":{\"perPage\":9,\"postType\":\"post\",\"inherit\":true},\"align\":\"wide\"} -->\n	<div class=\"wp-block-query alignwide\">\n		<!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n\n			<!-- wp:group {\"className\":\"tb-card tb-reveal\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\"}} -->\n			<div class=\"wp-block-group tb-card tb-reveal has-alabaster-background-color has-background\">\n				<!-- wp:post-featured-image {\"aspectRatio\":\"3/2\"} /-->\n				<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"},\"blockGap\":\"0.625rem\"}},\"layout\":{\"type\":\"constrained\"}} -->\n				<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--30)\">\n					<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"large\"} /-->\n					<!-- wp:post-date {\"textColor\":\"muted\",\"fontSize\":\"small\"} /-->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:group -->\n\n		<!-- /wp:post-template -->\n\n		<!-- wp:query-pagination {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"},\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}}} -->\n			<!-- wp:query-pagination-previous /-->\n			<!-- wp:query-pagination-numbers /-->\n			<!-- wp:query-pagination-next /-->\n		<!-- /wp:query-pagination -->\n\n		<!-- wp:query-no-results -->\n			<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"muted\"} -->\n			<p class=\"has-text-align-center has-muted-color has-text-color\">Nothing here yet.</p>\n			<!-- /wp:paragraph -->\n		<!-- /wp:query-no-results -->\n	</div>\n	<!-- /wp:query -->\n\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'All Archives', 'Displays any archive, including posts by a single author, category, tag, taxonomy, custom post type, and date. This template will serve as a fallback when more specific templates (e.g. Category or Tag) cannot be found.', 'publish', 'closed', 'closed', '', 'archive', '', '', '2026-08-14 22:29:56', '2026-08-14 22:29:56', '', 0, 'https://violet-wren-104886.hostingersite.com/archive/', 0, 'wp_template', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(103, 1, '2026-08-14 22:39:45', '2026-08-14 22:39:45', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- The hub supplies its own H1 inside the Rooted hero, so the page title is\n     not rendered here. Content comes from the Renton category, not this file. -->\n<!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-renton-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<!-- wp:html -->\n	<style>\n	.tb-renton-page{background:#fbf6eb;color:#243042}.tb-renton-hero.tb-renton-hero--split{min-height:480px;display:flex;align-items:stretch;background:#fbf6eb;padding-block:0;overflow:hidden}.tb-renton-hero__photo{flex:1 1 52%;background:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/image.png\') center/cover no-repeat;position:relative;min-height:320px}.tb-renton-hero__photo::before{content:\'\';position:absolute;inset:0;background:linear-gradient(90deg,#fbf6eb 0%,rgba(251,246,235,0) 20%)}.tb-renton-hero--split .tb-renton-hero__inner{flex:1 1 48%;width:auto;max-width:560px;margin:0;padding:56px 48px;display:flex;flex-direction:column;justify-content:center;box-sizing:border-box}.tb-renton-stamp{width:132px;height:132px;margin-bottom:26px}.tb-renton-title{max-width:720px;margin:0 0 18px;color:#10263f;text-transform:uppercase;letter-spacing:.01em;font-size:clamp(2.4rem,5vw,4rem);line-height:1.02}.tb-renton-dek{max-width:650px;color:#243042;font-size:clamp(1.05rem,1.6vw,1.25rem);line-height:1.65}.tb-renton-featured,.tb-renton-latest{padding:84px 24px}.tb-renton-featured .tb-page-shell,.tb-renton-latest .tb-page-shell,.tb-renton-editorial .tb-page-shell{max-width:1180px;margin:auto}.tb-renton-feature-card{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(280px,.7fr);gap:42px;align-items:center;background:#fff;padding:24px;border:1px solid #e4dccd}.tb-renton-feature-card .wp-block-post-featured-image{grid-row:1/6;margin:0}.tb-renton-feature-card:before{content:\"\";display:block;grid-column:1;grid-row:1/6;min-height:430px;background:url(\'https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-hero.jpg\') center/cover no-repeat}.tb-renton-feature-card>p,.tb-renton-feature-card>h2,.tb-renton-feature-card>.wp-block-post-terms,.tb-renton-feature-card>.wp-block-post-date{grid-column:2}.tb-renton-feature-card h2{font-size:clamp(2rem,4vw,3.25rem);line-height:1.05}.tb-renton-topics{background:#d9a441;padding:26px 24px}.tb-renton-topics .tb-page-shell{display:flex;justify-content:center;gap:12px 32px;flex-wrap:wrap}.tb-renton-topics a{color:#10263f;font-weight:700}.tb-renton-latest .wp-block-post-template{gap:28px}.tb-renton-card{background:#fff;overflow:hidden;border:1px solid #e4dccd;height:100%}.tb-renton-card__body{padding:22px}.tb-renton-card h3{font-size:1.75rem;line-height:1.15}.tb-renton-editorial{padding:80px 24px}.tb-renton-editorial--navy{background:#10263f;color:#fff}.tb-renton-editorial--mustard{background:#f7ecd3;border-top:3px solid #d9a441;border-bottom:3px solid #d9a441}.tb-renton-editorial h2{margin:0 0 18px;font-size:clamp(2.25rem,5vw,4rem);line-height:1.05}.tb-renton-editorial__intro{max-width:720px;font-size:1.15rem;line-height:1.7}.tb-renton-favorites{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;margin-top:36px}.tb-renton-favorite{background:#fff;color:#243042;padding:0 0 22px;border-top:6px solid #d9a441;overflow:hidden}.tb-renton-favorite img{width:100%;aspect-ratio:4/3;object-fit:cover}.tb-renton-favorite div{padding:18px 18px 0}.tb-renton-favorite strong{display:block;margin-bottom:8px;font-size:1.2rem}.tb-renton-actions{display:flex;gap:14px;flex-wrap:wrap;margin-top:28px}.tb-renton-action{display:inline-block;padding:14px 22px;background:#d9a441;color:#10263f;font-weight:700;text-decoration:none}.tb-renton-action--navy{background:#10263f;color:#fff}.tb-renton-cta{padding:72px 24px}.tb-renton-cta .tb-page-shell{max-width:900px;margin:auto}.tb-renton-cta h2{font-size:clamp(2.25rem,5vw,4rem)}@media(max-width:760px){.tb-renton-hero{min-height:560px;background-position:62% center}.tb-renton-hero__inner{padding:48px 0}.tb-renton-feature-card{grid-template-columns:1fr}.tb-renton-feature-card .wp-block-post-featured-image{grid-row:auto}.tb-renton-feature-card:before{grid-column:1;grid-row:auto;min-height:280px}.tb-renton-feature-card>p,.tb-renton-feature-card>h2,.tb-renton-feature-card>.wp-block-post-terms,.tb-renton-feature-card>.wp-block-post-date{grid-column:1}.tb-renton-favorites{grid-template-columns:1fr}.tb-renton-featured,.tb-renton-latest,.tb-renton-editorial{padding:56px 20px}}\n	.tb-renton-stamp--official{width:170px;height:170px;object-fit:contain;filter:none;transform:scale(1.9);clip-path:circle(27% at 50% 50%);transform-origin:center;margin:22px 0 52px 0}.tb-renton-page .tb-eyebrow{color:#d9a441!important}.tb-renton-page a{--wp--preset--color--coral:#d9a441}body.page-id-53 header a[href=\"/contact/\"],body.page-id-53 header .wp-element-button{background:#d9a441!important;color:#10263f!important}body.page-id-53 .has-coral-background-color{background-color:#d9a441!important}body.page-id-53 .has-coral-color{color:#d9a441!important}body.page-id-53 footer .tb-eyebrow{color:#d9a441!important}.tb-renton-series,.tb-renton-categories,.tb-renton-guides{padding:76px 24px}.tb-renton-series .tb-page-shell,.tb-renton-categories .tb-page-shell,.tb-renton-guides .tb-page-shell{max-width:1180px;margin:auto}.tb-renton-section-title{text-align:center;color:#10263f;font-size:clamp(2rem,4vw,3.25rem);margin:0 0 36px}.tb-renton-series-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.tb-renton-series-card{position:relative;color:#10263f;text-decoration:none}.tb-renton-series-card img{width:100%;aspect-ratio:16/10;object-fit:cover;border-radius:6px}.tb-renton-play{position:absolute;left:50%;top:42%;transform:translate(-50%,-50%);width:54px;height:54px;border-radius:50%;display:grid;place-items:center;background:#fbf6eb;color:#10263f;font-size:22px}.tb-renton-series-card strong{display:block;font-family:Cormorant Garamond,serif;font-size:1.55rem;margin-top:12px}.tb-renton-series-card small{color:#b58a08;font-weight:700}.tb-renton-category-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.tb-renton-category{min-height:250px;display:flex;align-items:flex-end;padding:20px;color:#fff!important;text-decoration:none;background-size:cover;background-position:center;border-radius:6px;box-shadow:inset 0 -110px 80px rgba(11,31,59,.78)}.tb-renton-category strong{font-size:1.05rem;letter-spacing:.08em;text-transform:uppercase}.tb-renton-guide-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.tb-renton-guide{display:grid;grid-template-columns:120px 1fr;gap:18px;align-items:center;padding:18px;background:#fff;border:1px solid #e4dccd;color:#10263f!important;text-decoration:none}.tb-renton-guide img{width:120px;height:120px;object-fit:cover}.tb-renton-guide strong{font-family:Cormorant Garamond,serif;font-size:1.45rem;line-height:1.1}.tb-renton-guide span{display:block;margin-top:8px;color:#a97f06;font-size:.78rem;font-weight:700;text-transform:uppercase}.tb-renton-video-wrap{position:relative;max-width:860px;margin:0 auto;aspect-ratio:16/9;border-radius:6px;overflow:hidden;box-shadow:0 20px 60px rgba(16,38,63,.25)}.tb-renton-video-wrap iframe{position:absolute;inset:0;width:100%;height:100%;border:0}.tb-renton-video-caption{text-align:center;color:#6b7280;font-size:.95rem;margin:18px auto 0;max-width:560px}@media(max-width:760px){.tb-renton-series-grid,.tb-renton-category-grid,.tb-renton-guide-grid{grid-template-columns:1fr}.tb-renton-category{min-height:210px}.tb-renton-series,.tb-renton-categories,.tb-renton-guides{padding:52px 20px}.tb-renton-stamp--official{width:118px;height:118px}}.tb-renton-cta-duo{display:grid;grid-template-columns:1fr 1fr}.tb-renton-cta-duo__col{padding:64px 40px}.tb-renton-cta-duo__col--mustard{background:#f7ecd3;border-top:3px solid #d9a441;border-bottom:3px solid #d9a441}.tb-renton-cta-duo__col h2{margin:0 0 16px;font-size:clamp(1.9rem,3vw,2.6rem);line-height:1.1}.tb-renton-cta-duo__col .tb-renton-editorial__intro{font-size:1.05rem;max-width:100%}.tb-renton-cta-duo__secondary{display:inline-flex;align-items:center;font-weight:700;color:#10263f;text-decoration:underline;padding:14px 0;margin-left:6px}@media(max-width:800px){.tb-renton-cta-duo{grid-template-columns:1fr}}\n.tb-renton-hero__links .tb-renton-button{background:#10263f;color:#fff;padding:.9rem 1.9rem;border-radius:2px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;font-size:.8rem;text-decoration:none;display:inline-block;transition:background .2s;border:1px solid #10263f}\n.tb-renton-hero__links .tb-renton-button:hover{background:#0b1c30}\n.tb-renton-hero__links .tb-renton-link{display:inline-flex;align-items:center;gap:.4rem;padding:.9rem 1.6rem;border:1px solid #10263f;color:#10263f;font-weight:600;letter-spacing:.08em;text-transform:uppercase;font-size:.8rem;text-decoration:none;border-radius:2px;transition:background .2s,color .2s}\n.tb-renton-hero__links .tb-renton-link:hover{background:#10263f;color:#fff}\n.tb-renton-editorial--navy h2{font-family:var(--wp--preset--font-family--sans);font-weight:600;font-size:clamp(1.4rem,2.4vw,1.9rem);letter-spacing:.01em;line-height:1.35;color:#fff;text-transform:none}\n@media(max-width:800px){.tb-renton-hero.tb-renton-hero--split{flex-direction:column}.tb-renton-hero--split .tb-renton-hero__inner{max-width:100%;padding:40px 24px}.tb-renton-hero__photo{min-height:260px}.tb-renton-hero__photo::before{background:linear-gradient(180deg,#fbf6eb 0%,rgba(251,246,235,0) 20%)}}\n</style>\n	<!-- /wp:html -->\n\n	<!-- The Journal newsletter pattern is deliberately not reused here: it is\n	     styled for the Journal page and renders unreadably in this context.\n	     The blueprint asks for a Renton-specific signup with its own copy,\n	     which is a separate build. -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-renton\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/renton-hub\",\"name\":\"Renton Hub\",\"categories\":[\"featured\"]}} -->\n<!-- wp:html -->\n	<section class=\"tb-renton-hero tb-renton-hero--split\" aria-labelledby=\"renton-title\">\n		<div class=\"tb-renton-hero__photo\"></div>\n		<div class=\"tb-page-shell tb-renton-hero__inner\">\n						<img class=\"tb-renton-stamp tb-renton-stamp--official\" src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/3.png\" alt=\"Rooted in Renton, established 1901\" width=\"1536\" height=\"1536\">\n			<h1 id=\"renton-title\" class=\"tb-renton-title\">Rooted in Renton</h1>\n			<p class=\"tb-renton-dek\">Local stories, favorite places and the people who make Renton feel like home.</p>\n			<p class=\"tb-renton-hero__links\">\n				<a class=\"tb-renton-button\" href=\"#renton-latest\">Explore the latest stories</a>\n				<a class=\"tb-renton-link\" href=\"#renton-series\">Watch the series <span aria-hidden=\"true\">&rarr;</span></a>\n			</p>\n		</div>\n	</section>\n	<!-- /wp:html -->\n\n	<!-- wp:group {\"className\":\"tb-renton-featured\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-renton-featured\">\n		<div class=\"tb-page-shell\">\n\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">Featured Story</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:query {\"queryId\":40,\"query\":{\"perPage\":1,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"include\",\"include\":[59],\"taxQuery\":{\"category\":[23]},\"inherit\":false},\"align\":\"wide\"} -->\n			<div class=\"wp-block-query alignwide\">\n				<!-- wp:post-template -->\n					<!-- wp:group {\"className\":\"tb-renton-feature-card\",\"layout\":{\"type\":\"default\"}} -->\n					<div class=\"wp-block-group tb-renton-feature-card\">\n						<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"16/9\"} /-->\n						<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-renton-kicker\"} /-->\n						<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"x-large\"} /-->\n						<!-- wp:post-excerpt {\"excerptLength\":34} /-->\n						<!-- wp:post-date {\"format\":\"F j, Y\",\"className\":\"tb-renton-date\"} /-->\n					</div>\n					<!-- /wp:group -->\n				<!-- /wp:post-template -->\n\n				<!-- wp:query-no-results -->\n					<!-- wp:paragraph {\"className\":\"tb-renton-empty\"} -->\n					<p class=\"tb-renton-empty\">The first Renton stories are being written now. In the meantime, tell Tanya what you would like to see covered — a favourite restaurant, a park worth knowing about, or a corner of the city that deserves more attention.</p>\n					<!-- /wp:paragraph -->\n\n					<!-- wp:buttons -->\n					<div class=\"wp-block-buttons\">\n						<!-- wp:button {\"backgroundColor\":\"ink\"} -->\n						<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-ink-background-color has-background wp-element-button\" href=\"/contact/\">Suggest a Renton story</a></div>\n						<!-- /wp:button -->\n					</div>\n					<!-- /wp:buttons -->\n				<!-- /wp:query-no-results -->\n			</div>\n			<!-- /wp:query -->\n\n		</div>\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-series\" id=\"renton-series\"><div class=\"tb-page-shell\"><h2 class=\"tb-renton-section-title\">Watch the Series</h2><div class=\"tb-renton-video-wrap\"><iframe src=\"https://www.youtube.com/embed/FcI3-ix5iqE\" title=\"What Community Means to Me | Tanya Barrans, Your Neighborhood Realtor in Renton, WA\" loading=\"lazy\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe></div><p class=\"tb-renton-video-caption\">From the Beyond the Sale podcast — what community means to Tanya, and why Renton is home.</p><div class=\"tb-renton-actions\" style=\"justify-content:center\"><a class=\"tb-renton-action tb-renton-action--navy\" href=\"https://www.instagram.com/tanyabarrans/\" target=\"_blank\" rel=\"noopener noreferrer\">More Rooted in Renton on Instagram</a></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-categories\"><div class=\"tb-page-shell\"><h2 class=\"tb-renton-section-title\">Explore by Category</h2><div class=\"tb-renton-category-grid\"><a class=\"tb-renton-category\" href=\"/category/renton/eat-drink/\" style=\"background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg\')\"><strong>Eat &amp; Drink →</strong></a><a class=\"tb-renton-category\" href=\"/category/renton/parks-outdoors/\" style=\"background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-kitchen-garden.jpg\')\"><strong>Parks &amp; Outdoors →</strong></a><a class=\"tb-renton-category\" href=\"/category/renton/local-businesses/\" style=\"background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-front-door.jpg\')\"><strong>Local Businesses →</strong></a><a class=\"tb-renton-category\" href=\"/category/renton/community-events/\" style=\"background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg\')\"><strong>Events →</strong></a></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-editorial tb-renton-editorial--navy\"><div class=\"tb-page-shell\"><p class=\"tb-eyebrow\">Tanya\'s Current Renton Favorites</p><h2>A few places worth knowing right now.</h2><p class=\"tb-renton-editorial__intro\">Personal picks from around the city—the places, walks, and small businesses Tanya is genuinely enjoying and recommending.</p><div class=\"tb-renton-favorites\"><article class=\"tb-renton-favorite\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-kitchen-garden.jpg\" alt=\"\"><div><strong>The local plant shop</strong><span>Greenery, good advice, and a reason to linger.</span></div></article><article class=\"tb-renton-favorite\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\" alt=\"\"><div><strong>Downtown Renton</strong><span>The mural, independent businesses, and neighborhood character.</span></div></article><article class=\"tb-renton-favorite\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg\" alt=\"\"><div><strong>A cozy coffee stop</strong><span>A warm drink, a friendly corner, and time to catch up.</span></div></article><article class=\"tb-renton-favorite\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-hero.jpg\" alt=\"\"><div><strong>Renton Farmers Market</strong><span>Local finds, familiar faces, and a seasonal tradition.</span></div></article></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:group {\"className\":\"tb-renton-latest\",\"layout\":{\"type\":\"default\"},\"anchor\":\"renton-latest\"} -->\n	<div class=\"wp-block-group tb-renton-latest\" id=\"renton-latest\">\n		<div class=\"tb-page-shell\">\n\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">More From Renton</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:query {\"queryId\":41,\"query\":{\"perPage\":6,\"pages\":0,\"offset\":1,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"taxQuery\":{\"category\":[23]},\"inherit\":false},\"align\":\"wide\"} -->\n			<div class=\"wp-block-query alignwide\">\n				<!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n					<!-- wp:group {\"className\":\"tb-card tb-renton-card\",\"layout\":{\"type\":\"default\"}} -->\n					<div class=\"wp-block-group tb-card tb-renton-card\">\n						<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"4/3\"} /-->\n						<!-- wp:group {\"className\":\"tb-renton-card__body\",\"layout\":{\"type\":\"default\"}} -->\n						<div class=\"wp-block-group tb-renton-card__body\">\n							<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-renton-kicker\"} /-->\n							<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"large\"} /-->\n							<!-- wp:post-date {\"format\":\"F j, Y\",\"className\":\"tb-renton-date\"} /-->\n						</div>\n						<!-- /wp:group -->\n					</div>\n					<!-- /wp:group -->\n				<!-- /wp:post-template -->\n\n				<!-- wp:query-no-results -->\n					<!-- wp:paragraph {\"className\":\"tb-renton-empty\"} -->\n					<p class=\"tb-renton-empty\">More Renton stories are on the way.</p>\n					<!-- /wp:paragraph -->\n				<!-- /wp:query-no-results -->\n			</div>\n			<!-- /wp:query -->\n\n		</div>\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-guides\"><div class=\"tb-page-shell\"><h2 class=\"tb-renton-section-title\">Renton Guide Collection</h2><div class=\"tb-renton-guide-grid\"><a class=\"tb-renton-guide\" href=\"/20-things-to-do-in-renton-this-weekend-from-someone-who-lives-here/\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-hero.jpg\" alt=\"\"><div><strong>The Ultimate Renton Weekend Guide</strong><span>Read guide →</span></div></a><a class=\"tb-renton-guide\" href=\"/best-renton-neighborhoods-for-every-lifestyle-a-locals-honest-guide/\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-front-door.jpg\" alt=\"\"><div><strong>A Local\'s Guide to Renton Neighborhoods</strong><span>Read guide →</span></div></a><a class=\"tb-renton-guide\" href=\"/moving-to-renton-wa-a-practical-guide-to-planning-your-move/\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg\" alt=\"\"><div><strong>Moving to Renton: A Practical Guide</strong><span>Read guide →</span></div></a></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-cta-duo\">\n		<div class=\"tb-renton-cta-duo__col tb-renton-cta-duo__col--mustard\">\n			<p class=\"tb-eyebrow\">Neighborhood Connection</p>\n			<h2>Love the place? Explore what it\'s like to live nearby.</h2>\n			<p class=\"tb-renton-editorial__intro\">Connect the restaurants, parks, businesses, and everyday stories you discover here with Renton\'s neighborhoods.</p>\n			<div class=\"tb-renton-actions\">\n				<a class=\"tb-renton-action tb-renton-action--navy\" href=\"/neighborhoods/\">Explore Renton neighborhoods</a>\n				<a class=\"tb-renton-cta-duo__secondary\" href=\"/best-renton-neighborhoods-for-every-lifestyle-a-locals-honest-guide/\">Read the neighborhood guide &rarr;</a>\n			</div>\n		</div>\n		<div class=\"tb-renton-cta-duo__col\">\n			<p class=\"tb-eyebrow\">Community Stories</p>\n			<h2>Know a Renton story we should tell?</h2>\n			<p class=\"tb-renton-editorial__intro\">Share a local business, community event, interesting person, hidden gem, or story idea. Rooted in Renton should be shaped by the people who call the city home.</p>\n			<div class=\"tb-renton-actions\">\n				<a class=\"tb-renton-action\" href=\"/contact/\">Suggest a Renton story</a>\n			</div>\n		</div>\n	</section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-cta\" aria-labelledby=\"renton-cta-title\">\n		<div class=\"tb-page-shell\">\n			<h2 id=\"renton-cta-title\">Thinking about making Renton home?</h2>\n			<p>Or making a move within the city? Tanya can walk you through the neighbourhoods and the market without the sales pressure.</p>\n			<p class=\"tb-renton-cta__links\">\n				<a class=\"tb-renton-button tb-renton-button--light\" href=\"/contact/\">Ask Tanya a question</a>\n				<a class=\"tb-renton-link tb-renton-link--light\" href=\"/buy/\">Explore buying in Renton <span aria-hidden=\"true\">&rarr;</span></a>\n			</p>\n		</div>\n	</section>\n	<!-- /wp:html -->\n<!-- /wp:group -->\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'page-renton', '', 'publish', 'closed', 'closed', '', 'page-renton', '', '', '2026-08-21 22:44:38', '2026-08-21 22:44:38', '', 0, 'https://violet-wren-104886.hostingersite.com/page-renton/', 0, 'wp_template', '', 0),
(104, 1, '2026-08-14 22:40:54', '2026-08-14 22:40:54', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- The hub supplies its own H1 inside the Rooted hero, so the page title is\n     not rendered here. Content comes from the Renton category, not this file. -->\n<!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-renton-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-renton-page\">\n	<!-- wp:html -->\n	<style>\n	.tb-renton-page{background:#fbf7ee;color:#243653}.tb-renton-hero{min-height:660px;display:flex;align-items:flex-end;background:linear-gradient(90deg,rgba(28,45,78,.94) 0%,rgba(28,45,78,.78) 52%,rgba(28,45,78,.22) 100%),url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\') center/cover no-repeat}.tb-renton-hero__inner{width:min(1180px,calc(100% - 48px));margin:auto;padding:72px 0}.tb-renton-stamp{width:132px;height:132px;margin-bottom:26px}.tb-renton-title{max-width:720px;margin:0 0 18px;color:#fff;font-size:clamp(3rem,7vw,5.5rem);line-height:.95}.tb-renton-dek{max-width:650px;color:#fff;font-size:clamp(1.1rem,2vw,1.35rem);line-height:1.65}.tb-renton-featured,.tb-renton-latest{padding:84px 24px}.tb-renton-featured .tb-page-shell,.tb-renton-latest .tb-page-shell,.tb-renton-editorial .tb-page-shell{max-width:1180px;margin:auto}.tb-renton-feature-card{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(280px,.7fr);gap:42px;align-items:center;background:#fff;padding:24px;border:1px solid #e4dccd}.tb-renton-feature-card .wp-block-post-featured-image{grid-row:1/6;margin:0}.tb-renton-feature-card h2{font-size:clamp(2rem,4vw,3.25rem);line-height:1.05}.tb-renton-topics{background:#d5a719;padding:26px 24px}.tb-renton-topics .tb-page-shell{display:flex;justify-content:center;gap:12px 32px;flex-wrap:wrap}.tb-renton-topics a{color:#1c2d4e;font-weight:700}.tb-renton-latest .wp-block-post-template{gap:28px}.tb-renton-card{background:#fff;overflow:hidden;border:1px solid #e4dccd;height:100%}.tb-renton-card__body{padding:22px}.tb-renton-card h3{font-size:1.75rem;line-height:1.15}.tb-renton-editorial{padding:80px 24px}.tb-renton-editorial--navy{background:#1c2d4e;color:#fff}.tb-renton-editorial--mustard{background:#d5a719}.tb-renton-editorial h2{margin:0 0 18px;font-size:clamp(2.25rem,5vw,4rem);line-height:1.05}.tb-renton-editorial__intro{max-width:720px;font-size:1.15rem;line-height:1.7}.tb-renton-favorites{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:36px}.tb-renton-favorite{background:#fff;color:#243653;padding:28px;border-top:6px solid #d5a719}.tb-renton-favorite strong{display:block;margin-bottom:8px;font-size:1.2rem}.tb-renton-actions{display:flex;gap:14px;flex-wrap:wrap;margin-top:28px}.tb-renton-action{display:inline-block;padding:14px 22px;background:#d5a719;color:#1c2d4e;font-weight:700;text-decoration:none}.tb-renton-action--navy{background:#1c2d4e;color:#fff}.tb-renton-cta{padding:72px 24px}.tb-renton-cta .tb-page-shell{max-width:900px;margin:auto}.tb-renton-cta h2{font-size:clamp(2.25rem,5vw,4rem)}@media(max-width:760px){.tb-renton-hero{min-height:560px;background-position:62% center}.tb-renton-hero__inner{padding:48px 0}.tb-renton-feature-card{grid-template-columns:1fr}.tb-renton-feature-card .wp-block-post-featured-image{grid-row:auto}.tb-renton-favorites{grid-template-columns:1fr}.tb-renton-featured,.tb-renton-latest,.tb-renton-editorial{padding:56px 20px}}\n	</style>\n	<!-- /wp:html -->\n\n	<!-- The Journal newsletter pattern is deliberately not reused here: it is\n	     styled for the Journal page and renders unreadably in this context.\n	     The blueprint asks for a Renton-specific signup with its own copy,\n	     which is a separate build. -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-renton\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/renton-hub\",\"name\":\"Renton Hub\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-renton\">\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-hero\" aria-labelledby=\"renton-title\">\n		<div class=\"tb-page-shell tb-renton-hero__inner\">\n						<svg class=\"tb-renton-stamp\" viewBox=\"0 0 200 200\" role=\"img\" aria-label=\"Rooted in Renton, established 1901\">\n								<defs>\n					<path id=\"tb-stamp-arc-top\" d=\"M100,100 m-70,0 a70,70 0 1,1 140,0\" />\n					<path id=\"tb-stamp-arc-bottom\" d=\"M100,100 m-80,0 a80,80 0 1,0 160,0\" />\n				</defs>\n				<circle class=\"tb-stamp-rim\" cx=\"100\" cy=\"100\" r=\"98\" />\n				<circle class=\"tb-stamp-body\" cx=\"100\" cy=\"100\" r=\"91\" />\n				<circle class=\"tb-stamp-ring\" cx=\"100\" cy=\"100\" r=\"83\" />\n				<text class=\"tb-stamp-arc\">\n					<textPath href=\"#tb-stamp-arc-top\" startOffset=\"50%\" text-anchor=\"middle\">ROOTED IN</textPath>\n				</text>\n				<text class=\"tb-stamp-arc\">\n					<textPath href=\"#tb-stamp-arc-bottom\" startOffset=\"50%\" text-anchor=\"middle\">RENTON</textPath>\n				</text>\n								<text class=\"tb-stamp-initial\" x=\"100\" y=\"111\" text-anchor=\"middle\">R</text>\n				<text class=\"tb-stamp-est\" x=\"56\" y=\"95\" text-anchor=\"middle\">EST.</text>\n				<text class=\"tb-stamp-est\" x=\"144\" y=\"95\" text-anchor=\"middle\">1901</text>\n				<rect class=\"tb-stamp-rule\" x=\"46\" y=\"101\" width=\"20\" height=\"2\" />\n				<rect class=\"tb-stamp-rule\" x=\"134\" y=\"101\" width=\"20\" height=\"2\" />\n				<path class=\"tb-stamp-heart\" d=\"M100 131c-5-4.6-9-7.6-9-11.6a4.6 4.6 0 0 1 9-1.9 4.6 4.6 0 0 1 9 1.9c0 4-4 7-9 11.6z\" />\n			</svg>\n			<h1 id=\"renton-title\" class=\"tb-renton-title\">Rooted in Renton</h1>\n			<p class=\"tb-renton-dek\">Local stories, favorite places and the people who make Renton feel like home.</p>\n			<p class=\"tb-renton-hero__links\">\n				<a class=\"tb-renton-button\" href=\"#renton-latest\">Explore the latest stories</a>\n				<a class=\"tb-renton-link\" href=\"https://www.instagram.com/tanyabarrans/\" target=\"_blank\" rel=\"noopener noreferrer\">Watch the series <span aria-hidden=\"true\">&rarr;</span></a>\n			</p>\n		</div>\n	</section>\n	<!-- /wp:html -->\n\n	<!-- wp:group {\"className\":\"tb-renton-featured\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-renton-featured\">\n		<div class=\"tb-page-shell\">\n\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">Featured Story</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:query {\"queryId\":40,\"query\":{\"perPage\":1,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"include\":[59],\"taxQuery\":{\"category\":[23]},\"inherit\":false},\"align\":\"wide\"} -->\n			<div class=\"wp-block-query alignwide\">\n				<!-- wp:post-template -->\n					<!-- wp:group {\"className\":\"tb-renton-feature-card\",\"layout\":{\"type\":\"default\"}} -->\n					<div class=\"wp-block-group tb-renton-feature-card\">\n						<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"16/9\"} /-->\n						<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-renton-kicker\"} /-->\n						<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"x-large\"} /-->\n						<!-- wp:post-excerpt {\"excerptLength\":34} /-->\n						<!-- wp:post-date {\"format\":\"F j, Y\",\"className\":\"tb-renton-date\"} /-->\n					</div>\n					<!-- /wp:group -->\n				<!-- /wp:post-template -->\n\n				<!-- wp:query-no-results -->\n					<!-- wp:paragraph {\"className\":\"tb-renton-empty\"} -->\n					<p class=\"tb-renton-empty\">The first Renton stories are being written now. In the meantime, tell Tanya what you would like to see covered — a favourite restaurant, a park worth knowing about, or a corner of the city that deserves more attention.</p>\n					<!-- /wp:paragraph -->\n\n					<!-- wp:buttons -->\n					<div class=\"wp-block-buttons\">\n						<!-- wp:button {\"backgroundColor\":\"ink\"} -->\n						<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-ink-background-color has-background wp-element-button\" href=\"/contact/\">Suggest a Renton story</a></div>\n						<!-- /wp:button -->\n					</div>\n					<!-- /wp:buttons -->\n				<!-- /wp:query-no-results -->\n			</div>\n			<!-- /wp:query -->\n\n		</div>\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:html -->\n	<nav class=\"tb-renton-topics\" aria-label=\"Renton topics\">\n		<div class=\"tb-page-shell\">\n			<a href=\"/category/renton/eat-drink/\">Eat &amp; Drink</a>\n			<a href=\"/category/renton/parks-outdoors/\">Parks &amp; Outdoors</a>\n			<a href=\"/category/renton/local-businesses/\">Local Businesses</a>\n			<a href=\"/category/renton/community-events/\">Community Events</a>\n			<a href=\"/category/renton/neighborhood-stories/\">Neighborhood Stories</a>\n		</div>\n	</nav>\n	<!-- /wp:html -->\n\n	<!-- wp:group {\"className\":\"tb-renton-latest\",\"layout\":{\"type\":\"default\"},\"anchor\":\"renton-latest\"} -->\n	<div class=\"wp-block-group tb-renton-latest\" id=\"renton-latest\">\n		<div class=\"tb-page-shell\">\n\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">More From Renton</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:query {\"queryId\":41,\"query\":{\"perPage\":6,\"pages\":0,\"offset\":1,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"taxQuery\":{\"category\":[23]},\"inherit\":false},\"align\":\"wide\"} -->\n			<div class=\"wp-block-query alignwide\">\n				<!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n					<!-- wp:group {\"className\":\"tb-card tb-renton-card\",\"layout\":{\"type\":\"default\"}} -->\n					<div class=\"wp-block-group tb-card tb-renton-card\">\n						<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"4/3\"} /-->\n						<!-- wp:group {\"className\":\"tb-renton-card__body\",\"layout\":{\"type\":\"default\"}} -->\n						<div class=\"wp-block-group tb-renton-card__body\">\n							<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-renton-kicker\"} /-->\n							<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"large\"} /-->\n							<!-- wp:post-date {\"format\":\"F j, Y\",\"className\":\"tb-renton-date\"} /-->\n						</div>\n						<!-- /wp:group -->\n					</div>\n					<!-- /wp:group -->\n				<!-- /wp:post-template -->\n\n				<!-- wp:query-no-results -->\n					<!-- wp:paragraph {\"className\":\"tb-renton-empty\"} -->\n					<p class=\"tb-renton-empty\">More Renton stories are on the way.</p>\n					<!-- /wp:paragraph -->\n				<!-- /wp:query-no-results -->\n			</div>\n			<!-- /wp:query -->\n\n		</div>\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-editorial tb-renton-editorial--navy\"><div class=\"tb-page-shell\"><p class=\"tb-eyebrow\">Tanya\'s Current Renton Favorites</p><h2>A few places worth knowing right now.</h2><p class=\"tb-renton-editorial__intro\">Personal picks from around the city—the places, walks, and small businesses Tanya is genuinely enjoying and recommending.</p><div class=\"tb-renton-favorites\"><article class=\"tb-renton-favorite\"><strong>A favorite local walk</strong><span>Gene Coulon Memorial Beach Park when the lake is quiet.</span></article><article class=\"tb-renton-favorite\"><strong>A downtown stop</strong><span>The I Heart Renton mural and the independent businesses nearby.</span></article><article class=\"tb-renton-favorite\"><strong>A seasonal plan</strong><span>A morning at the Renton Farmers Market followed by lunch downtown.</span></article></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-editorial tb-renton-editorial--mustard\"><div class=\"tb-page-shell\"><p class=\"tb-eyebrow\">Neighborhood Connection</p><h2>Love the place? Explore what it is like to live nearby.</h2><p class=\"tb-renton-editorial__intro\">Connect the restaurants, parks, businesses, and everyday stories you discover here with Renton\'s neighborhoods.</p><div class=\"tb-renton-actions\"><a class=\"tb-renton-action tb-renton-action--navy\" href=\"/neighborhoods/\">Explore Renton neighborhoods</a><a class=\"tb-renton-action tb-renton-action--navy\" href=\"/best-renton-neighborhoods-for-every-lifestyle-a-locals-honest-guide/\">Read the neighborhood guide</a></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-editorial\"><div class=\"tb-page-shell\"><p class=\"tb-eyebrow\">Community Stories</p><h2>Know a Renton story we should tell?</h2><p class=\"tb-renton-editorial__intro\">Share a local business, community event, interesting person, hidden gem, or story idea. Rooted in Renton should be shaped by the people who call the city home.</p><div class=\"tb-renton-actions\"><a class=\"tb-renton-action\" href=\"/contact/\">Suggest a Renton story</a></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-cta\" aria-labelledby=\"renton-cta-title\">\n		<div class=\"tb-page-shell\">\n			<h2 id=\"renton-cta-title\">Thinking about making Renton home?</h2>\n			<p>Or making a move within the city? Tanya can walk you through the neighbourhoods and the market without the sales pressure.</p>\n			<p class=\"tb-renton-cta__links\">\n				<a class=\"tb-renton-button tb-renton-button--light\" href=\"/contact/\">Ask Tanya a question</a>\n				<a class=\"tb-renton-link tb-renton-link--light\" href=\"/buy/\">Explore buying in Renton <span aria-hidden=\"true\">&rarr;</span></a>\n			</p>\n		</div>\n	</section>\n	<!-- /wp:html -->\n\n</div>\n<!-- /wp:group -->\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'page-renton', '', 'inherit', 'closed', 'closed', '', '103-revision-v1', '', '', '2026-08-14 22:40:54', '2026-08-14 22:40:54', '', 103, 'https://violet-wren-104886.hostingersite.com/?p=104', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(105, 1, '2026-08-14 22:41:27', '2026-08-14 22:41:27', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- The hub supplies its own H1 inside the Rooted hero, so the page title is\n     not rendered here. Content comes from the Renton category, not this file. -->\n<!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-renton-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-renton-page\">\n	<!-- wp:html -->\n	<style>\n	.tb-renton-page{background:#fbf7ee;color:#243653}.tb-renton-hero{min-height:660px;display:flex;align-items:flex-end;background:linear-gradient(90deg,rgba(28,45,78,.94) 0%,rgba(28,45,78,.78) 52%,rgba(28,45,78,.22) 100%),url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\') center/cover no-repeat}.tb-renton-hero__inner{width:min(1180px,calc(100% - 48px));margin:auto;padding:72px 0}.tb-renton-stamp{width:132px;height:132px;margin-bottom:26px}.tb-renton-title{max-width:720px;margin:0 0 18px;color:#fff;font-size:clamp(3rem,7vw,5.5rem);line-height:.95}.tb-renton-dek{max-width:650px;color:#fff;font-size:clamp(1.1rem,2vw,1.35rem);line-height:1.65}.tb-renton-featured,.tb-renton-latest{padding:84px 24px}.tb-renton-featured .tb-page-shell,.tb-renton-latest .tb-page-shell,.tb-renton-editorial .tb-page-shell{max-width:1180px;margin:auto}.tb-renton-feature-card{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(280px,.7fr);gap:42px;align-items:center;background:#fff;padding:24px;border:1px solid #e4dccd}.tb-renton-feature-card .wp-block-post-featured-image{grid-row:1/6;margin:0}.tb-renton-feature-card h2{font-size:clamp(2rem,4vw,3.25rem);line-height:1.05}.tb-renton-topics{background:#d5a719;padding:26px 24px}.tb-renton-topics .tb-page-shell{display:flex;justify-content:center;gap:12px 32px;flex-wrap:wrap}.tb-renton-topics a{color:#1c2d4e;font-weight:700}.tb-renton-latest .wp-block-post-template{gap:28px}.tb-renton-card{background:#fff;overflow:hidden;border:1px solid #e4dccd;height:100%}.tb-renton-card__body{padding:22px}.tb-renton-card h3{font-size:1.75rem;line-height:1.15}.tb-renton-editorial{padding:80px 24px}.tb-renton-editorial--navy{background:#1c2d4e;color:#fff}.tb-renton-editorial--mustard{background:#d5a719}.tb-renton-editorial h2{margin:0 0 18px;font-size:clamp(2.25rem,5vw,4rem);line-height:1.05}.tb-renton-editorial__intro{max-width:720px;font-size:1.15rem;line-height:1.7}.tb-renton-favorites{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:36px}.tb-renton-favorite{background:#fff;color:#243653;padding:28px;border-top:6px solid #d5a719}.tb-renton-favorite strong{display:block;margin-bottom:8px;font-size:1.2rem}.tb-renton-actions{display:flex;gap:14px;flex-wrap:wrap;margin-top:28px}.tb-renton-action{display:inline-block;padding:14px 22px;background:#d5a719;color:#1c2d4e;font-weight:700;text-decoration:none}.tb-renton-action--navy{background:#1c2d4e;color:#fff}.tb-renton-cta{padding:72px 24px}.tb-renton-cta .tb-page-shell{max-width:900px;margin:auto}.tb-renton-cta h2{font-size:clamp(2.25rem,5vw,4rem)}@media(max-width:760px){.tb-renton-hero{min-height:560px;background-position:62% center}.tb-renton-hero__inner{padding:48px 0}.tb-renton-feature-card{grid-template-columns:1fr}.tb-renton-feature-card .wp-block-post-featured-image{grid-row:auto}.tb-renton-favorites{grid-template-columns:1fr}.tb-renton-featured,.tb-renton-latest,.tb-renton-editorial{padding:56px 20px}}\n	</style>\n	<!-- /wp:html -->\n\n	<!-- The Journal newsletter pattern is deliberately not reused here: it is\n	     styled for the Journal page and renders unreadably in this context.\n	     The blueprint asks for a Renton-specific signup with its own copy,\n	     which is a separate build. -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-renton\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/renton-hub\",\"name\":\"Renton Hub\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-renton\">\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-hero\" aria-labelledby=\"renton-title\">\n		<div class=\"tb-page-shell tb-renton-hero__inner\">\n						<svg class=\"tb-renton-stamp\" viewBox=\"0 0 200 200\" role=\"img\" aria-label=\"Rooted in Renton, established 1901\">\n								<defs>\n					<path id=\"tb-stamp-arc-top\" d=\"M100,100 m-70,0 a70,70 0 1,1 140,0\" />\n					<path id=\"tb-stamp-arc-bottom\" d=\"M100,100 m-80,0 a80,80 0 1,0 160,0\" />\n				</defs>\n				<circle class=\"tb-stamp-rim\" cx=\"100\" cy=\"100\" r=\"98\" />\n				<circle class=\"tb-stamp-body\" cx=\"100\" cy=\"100\" r=\"91\" />\n				<circle class=\"tb-stamp-ring\" cx=\"100\" cy=\"100\" r=\"83\" />\n				<text class=\"tb-stamp-arc\">\n					<textPath href=\"#tb-stamp-arc-top\" startOffset=\"50%\" text-anchor=\"middle\">ROOTED IN</textPath>\n				</text>\n				<text class=\"tb-stamp-arc\">\n					<textPath href=\"#tb-stamp-arc-bottom\" startOffset=\"50%\" text-anchor=\"middle\">RENTON</textPath>\n				</text>\n								<text class=\"tb-stamp-initial\" x=\"100\" y=\"111\" text-anchor=\"middle\">R</text>\n				<text class=\"tb-stamp-est\" x=\"56\" y=\"95\" text-anchor=\"middle\">EST.</text>\n				<text class=\"tb-stamp-est\" x=\"144\" y=\"95\" text-anchor=\"middle\">1901</text>\n				<rect class=\"tb-stamp-rule\" x=\"46\" y=\"101\" width=\"20\" height=\"2\" />\n				<rect class=\"tb-stamp-rule\" x=\"134\" y=\"101\" width=\"20\" height=\"2\" />\n				<path class=\"tb-stamp-heart\" d=\"M100 131c-5-4.6-9-7.6-9-11.6a4.6 4.6 0 0 1 9-1.9 4.6 4.6 0 0 1 9 1.9c0 4-4 7-9 11.6z\" />\n			</svg>\n			<h1 id=\"renton-title\" class=\"tb-renton-title\">Rooted in Renton</h1>\n			<p class=\"tb-renton-dek\">Local stories, favorite places and the people who make Renton feel like home.</p>\n			<p class=\"tb-renton-hero__links\">\n				<a class=\"tb-renton-button\" href=\"#renton-latest\">Explore the latest stories</a>\n				<a c