(90193, 2, '2026-08-20 01:58:57', '2026-08-20 01:58:57', '<!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\">\n\n	<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"120px\"} -->\n	<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:120px\">\n		<!-- wp:image {\"id\":18,\"width\":\"120px\",\"height\":\"120px\",\"sizeSlug\":\"medium\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"999px\"}}} -->\n		<figure class=\"wp-block-image size-medium is-resized has-custom-border\"><img src=\"https://tanyabarrans.com/wp-content/uploads/2026/07/contact-circle-300x300.jpg\" alt=\"Tanya Barrans, Puget Sound real estate broker\" class=\"wp-image-18\" style=\"border-radius:999px;width:120px;height:120px;object-fit:cover\"/></figure>\n		<!-- /wp:image -->\n	</div>\n	<!-- /wp:column -->\n\n	<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n	<div class=\"wp-block-column is-vertically-aligned-center\">\n		<!-- wp:heading {\"level\":2,\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Tell me what you are trying to solve.</h2>\n		<!-- /wp:heading -->\n		<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n		<p class=\"has-muted-color has-text-color\">Whether you have a specific question or just want to explore what\'s possible, reach out anytime.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:column -->\n\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p><strong>Email:</strong> <a href=\"mailto:info@tanyabarrans.com\">info@tanyabarrans.com</a><br><strong>Phone:</strong> <a href=\"tel:+14255374728\">(425) 537-4728</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--30)\">\n	<!-- wp:button {\"cla