(90208, 2, '2026-08-20 05:40:06', '2026-08-20 05:40:06', '<!-- wp:columns {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\">\n\n	<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"120px\"} -->\n	<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:120px\">\n		<!-- wp:image {\"id\":18,\"width\":\"120px\",\"height\":\"120px\",\"sizeSlug\":\"medium\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"999px\"}}} -->\n		<figure class=\"wp-block-image size-medium is-resized has-custom-border\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/07/contact-circle-300x300.jpg\" alt=\"Tanya Barrans, Puget Sound real estate broker\" class=\"wp-image-18\" style=\"border-radius:999px;width:120px;height:120px;object-fit:cover\"/></figure>\n		<!-- /wp:image -->\n	</div>\n	<!-- /wp:column -->\n\n	<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n	<div class=\"wp-block-column is-vertically-aligned-center\">\n		<!-- wp:heading {\"level\":2,\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Tell me what you are trying to solve.</h2>\n		<!-- /wp:heading -->\n		<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n		<p class=\"has-muted-color has-text-color\">Whether you have a specific question or just want to explore what\'s possible, reach out anytime.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:column -->\n\n</div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p><strong>Email:</strong> <a href=\"mailto:info@tanyabarrans.com\">info@tanyabarrans.com</a><br><strong>Phone:</strong> <a href=\"tel:+14255374728\">(425) 537-4728</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--30)\">\n	<!-- wp:button {\"className\":\"tb-button-outline\",\"textColor\":\"ink\"} -->\n	<div class=\"wp-block-button tb-button-outline\"><a class=\"wp-block-button__link has-ink-color has-text-color wp-element-button\" href=\"https://calendar.app.google/zndHShd1Rm6W6Qb38\" target=\"_blank\" rel=\"noopener noreferrer\">Schedule a Call →</a></div>\n	<!-- /wp:button -->\n</div>\n<!-- /wp:buttons -->\n\n<!-- wp:paragraph {\"className\":\"tb-eyebrow\",\"textColor\":\"dusty-blush\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<p class=\"tb-eyebrow has-dusty-blush-color has-text-color\" style=\"margin-top:var(--wp--preset--spacing--40);margin-bottom:var(--wp--preset--spacing--20)\">Follow Along</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n<div class=\"tb-social-icons tb-social-icons--contact\">\n	<a href=\"https://www.facebook.com/tanyabarrans\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Tanya Barrans on Facebook\" class=\"tb-social-icon\">\n		<svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M22 12.06C22 6.5 17.52 2 12 2S2 6.5 2 12.06c0 5 3.66 9.15 8.44 9.94v-7.03H7.9v-2.91h2.54V9.85c0-2.5 1.49-3.89 3.77-3.89 1.09 0 2.24.2 2.24.2v2.46h-1.26c-1.24 0-1.63.77-1.63 1.56v1.88h2.78l-.44 2.91h-2.34V22c4.78-.79 8.44-4.94 8.44-9.94Z\"/></svg>\n	</a>\n	<a href=\"https://www.instagram.com/tanyabarrans/\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Tanya Barrans on Instagram\" class=\"tb-social-icon\">\n		<svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/><circle cx=\"17.5\" cy=\"6.5\" r=\"1\"/></svg>\n	</a>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"tb-content-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"var:preset|spacing|50\"}},\"border\":{\"radius\":\"8px\"}},\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group tb-content-card has-alabaster-background-color has-background\" style=\"border-radius:8px;margin-top:var(--wp--preset--spacing--50);padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\">\n	<!-- wp:pattern {\"slug\":\"tanya-barrans/contact-form\"} /-->\n</div>\n<!-- /wp:group -->\n', 'Contact', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-08-20 05:40:06', '2026-08-20 05:40:06', '', 11, 'https://violet-wren-104886.hostingersite.com/?p=90208', 0, 'revision', '', 0),
(90209, 2, '2026-08-20 05:40:06', '2026-08-20 05:40:06', '<!-- wp:pattern {\"slug\":\"tanya-barrans/about-intro\"} /-->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"720px\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--40)\">\n\n	<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-eyebrow\",\"textColor\":\"dusty-blush\"} -->\n<p class=\"has-text-align-center tb-eyebrow has-dusty-blush-color has-text-color\">Your Local Real Estate Expert</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:heading {\"level\":2,\"textAlign\":\"center\",\"fontSize\":\"x-large\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<h2 class=\"wp-block-heading has-text-align-center has-x-large-font-size\" style=\"margin-bottom:var(--wp--preset--spacing--40)\">Real relationships. Remarkable results.</h2>\n<!-- /wp:heading -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">Buying or selling a home is one of the biggest decisions you\'ll make, and it shouldn\'t feel like you\'re figuring it out alone. Whether you\'re searching for your first home, selling the place where you\'ve made years of memories, or simply wondering if now is the right time to make a move, my job is to give you honest advice, a smart strategy, and the confidence to move forward.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">I\'ve built my business around knowing the communities I serve — not just the statistics, but the neighborhoods, schools, commute patterns, hidden gems, and market trends that help my clients make better decisions. From Renton and Kent to Maple Valley, Covington, Newcastle, and the surrounding communities, I know what makes each area unique because this is home, too.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">Every client receives a customized marketing and pricing strategy designed around their goals, not a one-size-fits-all plan. Professional photography, Zillow Showcase, video, digital marketing, and strategic negotiation all work together to help you achieve the best possible outcome.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">But here\'s what I hope you\'ll remember most. By the time we get to closing, there\'s a good chance we\'ll be talking about more than real estate. I\'ll probably have you planning your first vegetable garden, convincing you to try homemade sourdough, or texting you recommendations for the best local spots after you\'ve moved in. Because while I love helping people buy and sell homes, my favorite part has always been the relationships that come with it.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"textColor\":\"muted\"} -->\n	<p class=\"has-muted-color has-text-color\">Many of my clients become friends, and some of my favorite compliments have nothing to do with the sale itself. They’re the messages that say, <em>“We couldn’t imagine going through this without you,”</em> or <em>“By the end, you felt like family.”</em></p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"align\":\"center\",\"fontFamily\":\"serif\",\"style\":{\"typography\":{\"fontStyle\":\"italic\",\"fontSize\":\"1.375rem\",\"lineHeight\":\"1.5\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n	<p class=\"has-text-align-center has-serif-font-family\" style=\"margin-top:var(--wp--preset--spacing--40);font-size:1.375rem;font-style:italic;line-height:1.5\">My goal isn\'t just to help you find the right house. It\'s to help you feel at home long before you unpack the first box.</p>\n	<!-- /wp:paragraph -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull has-alabaster-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--40)\">\n\n	<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-eyebrow\"} -->\n	<p class=\"has-text-align-center tb-eyebrow\">A Little More Personality</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"xx-large\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|40\"}}}} -->\n	<h2 class=\"wp-block-heading has-text-align-center has-xx-large-font-size\" style=\"margin-bottom:var(--wp--preset--spacing--40)\">Real estate, minus the stuffiness</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|30\"}}}} -->\n	<div class=\"wp-block-columns alignwide\">\n\n		<!-- wp:column {\"className\":\"tb-reveal\"} -->\n		<div class=\"wp-block-column tb-reveal\">\n			<!-- wp:image {\"id\":19,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"tb-card\",\"style\":{\"border\":{\"radius\":\"4px\"}}} -->\n			<figure class=\"wp-block-image size-full tb-card has-custom-border\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/07/gallery-1.jpg\" alt=\"Tanya Barrans smiling, seated\" class=\"wp-image-19\" style=\"border-radius:4px;aspect-ratio:3/4;object-fit:cover;width:100%\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-reveal\"} -->\n		<div class=\"wp-block-column tb-reveal\">\n			<!-- wp:image {\"id\":25,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"tb-card\",\"style\":{\"border\":{\"radius\":\"4px\"}}} -->\n			<figure class=\"wp-block-image size-full tb-card has-custom-border\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/07/gallery-2-new.jpg\" alt=\"Tanya Barrans smiling, hands on hips\" class=\"wp-image-25\" style=\"border-radius:4px;aspect-ratio:3/4;object-fit:cover;width:100%\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-reveal\"} -->\n		<div class=\"wp-block-column tb-reveal\">\n			<!-- wp:image {\"id\":21,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"tb-card\",\"style\":{\"border\":{\"radius\":\"4px\"}}} -->\n			<figure class=\"wp-block-image size-full tb-card has-custom-border\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/07/gallery-3.jpg\" alt=\"Tanya Barrans laughing, full length\" class=\"wp-image-21\" style=\"border-radius:4px;aspect-ratio:3/4;object-fit:cover;width:100%;object-position:top\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:column -->\n\n	</div>\n	<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n', 'About', '', 'inherit', 'closed', 'closed', '', '6-revision-v1', '', '', '2026-08-20 05:40:06', '2026-08-20 05:40:06', '', 6, 'https://violet-wren-104886.hostingersite.com/?p=90209', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(90210, 2, '2026-08-20 05:50:01', '2026-08-20 05:50:01', '<!-- wp:html -->\n<style>\n.tb-listings-page-hero{position:relative;min-height:clamp(520px,63vw,720px);display:flex;align-items:flex-end;background:linear-gradient(90deg,rgba(30,50,75,.23),rgba(30,50,75,.02)),url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/renton-pending.jpg\') center 55%/cover no-repeat;overflow:hidden}\n.tb-listings-page-hero:after{content:\"\";position:absolute;inset:50% 0 0;background:linear-gradient(transparent,rgba(26,47,70,.2));pointer-events:none}\n.tb-listings-hero-card{position:relative;z-index:1;width:min(650px,calc(100% - 48px));margin:0 0 -54px max(5vw,24px);padding:clamp(34px,5vw,64px);background:#fbf7f1;color:#344c6a;box-shadow:0 24px 70px rgba(35,52,73,.2)}\n.tb-listings-kicker,.tb-listings-page .tb-eyebrow{font-size:.72rem!important;letter-spacing:.18em;text-transform:uppercase;font-weight:700;color:#b46f88!important}\n.tb-listings-hero-card h2{font-size:clamp(2.7rem,5.4vw,5.2rem);line-height:.92;margin:.5rem 0 1.25rem;letter-spacing:-.03em}\n.tb-listings-hero-card h2 em{color:#c27e98;font-weight:inherit}\n.tb-listings-hero-card p{font-size:clamp(1rem,1.3vw,1.18rem);line-height:1.7;max-width:540px}\n.tb-listings-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px}\n.tb-listings-btn{display:inline-block;padding:14px 22px;background:#344c6a;color:white!important;text-decoration:none!important;font-size:.76rem;font-weight:700;letter-spacing:.09em;text-transform:uppercase;border:1px solid #344c6a;transition:.2s}\n.tb-listings-btn.alt{background:transparent;color:#344c6a!important}\n.tb-listings-btn:hover{transform:translateY(-2px);background:#c27e98;border-color:#c27e98;color:white!important}\n.tb-listings-page #current-listings{padding-top:125px!important}\n.tb-listings-page #current-listings .tb-sales-grid{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}\n.tb-listings-page #current-listings .tb-card{padding:0;background:#fff;box-shadow:0 15px 45px rgba(52,76,106,.1);overflow:hidden;transition:.25s}\n.tb-listings-page #current-listings .tb-card:hover{transform:translateY(-7px);box-shadow:0 22px 60px rgba(52,76,106,.17)}\n.tb-listings-page #current-listings .tb-sales-photo{height:clamp(300px,32vw,440px);overflow:hidden}\n.tb-listings-page .tb-sales-photo img{width:100%;height:100%;object-fit:cover;transition:transform .55s}\n.tb-listings-page .tb-card:hover .tb-sales-photo img{transform:scale(1.035)}\n.tb-listings-page #current-listings .tb-card p{padding-left:24px;padding-right:24px}\n.tb-listings-page #current-listings .tb-card p:first-of-type{font-size:1.45rem;margin-top:1.25rem!important}\n.tb-listings-page #current-listings .tb-card p:last-child{padding-bottom:24px;font-size:.88rem!important}\n.tb-listings-page .has-alabaster-background-color .tb-sales-grid{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}\n.tb-listings-page .has-alabaster-background-color .tb-card{padding:0 0 18px;background:#fff;box-shadow:0 10px 35px rgba(52,76,106,.08);overflow:hidden}\n.tb-listings-page .has-alabaster-background-color .tb-sales-photo{height:260px}\n.tb-listings-page .has-alabaster-background-color .tb-card p{padding-left:18px;padding-right:18px}\n.tb-listings-page .has-alabaster-background-color .tb-card strong{font-size:1.15rem}\n.tb-listings-proof{padding:32px 24px;background:#344c6a;color:#fff;display:grid;grid-template-columns:repeat(3,1fr);text-align:center;gap:1px}\n.tb-listings-proof div{padding:10px 20px;border-right:1px solid rgba(255,255,255,.25)}\n.tb-listings-proof div:last-child{border:0}.tb-listings-proof strong{display:block;font-family:Georgia,serif;font-size:1.35rem}.tb-listings-proof span{font-size:.7rem;letter-spacing:.13em;text-transform:uppercase;opacity:.8}\n.tb-listings-final{background:#344c6a;color:#fff;padding:clamp(60px,8vw,110px) 24px;text-align:center}\n.tb-listings-final-inner{max-width:850px;margin:auto}.tb-listings-final .tb-listings-kicker{color:#efb6c8!important}\n.tb-listings-final h2{color:#fff;font-size:clamp(2.4rem,4.8vw,4.7rem);line-height:1.03;margin:12px 0 18px}.tb-listings-final p{max-width:620px;margin:0 auto 28px;font-size:1.08rem;line-height:1.7}\n.tb-listings-final .tb-listings-btn{background:#efb6c8;border-color:#efb6c8;color:#344c6a!important}.tb-listings-final .tb-listings-btn.alt{background:transparent;color:#fff!important;border-color:rgba(255,255,255,.7)}\n@media(max-width:800px){.tb-listings-page-hero{min-height:560px;background-position:center}.tb-listings-hero-card{width:calc(100% - 32px);margin:0 16px -40px;padding:32px 25px}.tb-listings-page #current-listings{padding-top:92px!important}.tb-listings-page #current-listings .tb-sales-grid,.tb-listings-page .has-alabaster-background-color .tb-sales-grid{grid-template-columns:1fr}.tb-listings-page #current-listings .tb-sales-photo{height:360px}.tb-listings-proof{grid-template-columns:1fr}.tb-listings-proof div{border-right:0;border-bottom:1px solid rgba(255,255,255,.25)}}\n</style>\n<div class=\"tb-listings-page\">\n<section class=\"tb-listings-page-hero\">\n <div class=\"tb-listings-hero-card\">\n  <div class=\"tb-listings-kicker\">Renton · Kent · Covington · Puget Sound</div>\n  <h2>Homes with a story.<br><em>Moves with a strategy.</em></h2>\n  <p>See what is on the market now, then explore a selection of homes Tanya has helped buy and sell across the Puget Sound.</p>\n  <div class=\"tb-listings-actions\"><a class=\"tb-listings-btn\" href=\"/contact/\">Talk About Your Move</a><a class=\"tb-listings-btn alt\" href=\"#current-listings\">View Current Listings</a></div>\n </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"tb-topo-bg\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"sand\",\"layout\":{\"type\":\"constrain