(90224, 2, '2026-08-20 06:35:06', '2026-08-20 06:35:06', '<!-- wp:html --><style>body .wp-block-post-title{display:none!important}.tb-property-template{width:100vw;max-width:none!important;margin-left:calc(50% - 50vw);margin-top:-96px;overflow:hidden;color:#344c6a;background:#fbf8f4}.tb-property-template *{box-sizing:border-box}.tbp-hero{min-height:680px;position:relative;background:linear-gradient(90deg,rgba(30,48,70,.18),rgba(30,48,70,.02)),url(\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584.jpg\") center/cover no-repeat}.tbp-hero-card{position:absolute;left:max(4vw,24px);bottom:-65px;width:min(720px,calc(100% - 48px));padding:clamp(34px,5vw,66px);background:#fbf8f4;box-shadow:0 24px 70px rgba(52,76,106,.2)}.tbp-kicker{font-size:.7rem;letter-spacing:.18em;text-transform:uppercase;font-weight:700;color:#6f8a74}.tbp-hero h1{font-family:Georgia,serif;font-size:clamp(2.55rem,4.5vw,4.65rem);line-height:.95;margin:.6rem 0 1rem;color:#344c6a}.tbp-status{display:inline-block;padding:8px 12px;background:#d6a3b5;color:#344c6a;font-size:.68rem;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.tbp-price{font-family:Georgia,serif;font-size:1.7rem;margin:.6rem 0}.tbp-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:22px}.tbp-btn{display:inline-block;padding:14px 22px;background:#344c6a;color:#fff!important;text-decoration:none!important;text-transform:uppercase;letter-spacing:.1em;font-size:.7rem;font-weight:700;border:1px solid #344c6a}.tbp-btn.alt{background:transparent;color:#344c6a!important}.tbp-btn:hover{background:#6f8a74;border-color:#6f8a74;color:#fff!important}.tbp-facts{padding:110px 28px 42px;background:#dbc8b3;display:grid;grid-template-columns:repeat(5,1fr);gap:1px}.tbp-fact{text-align:center;padding:16px;border-right:1px solid rgba(52,76,106,.25)}.tbp-fact:last-child{border:0}.tbp-fact strong{display:block;font-family:Georgia,serif;font-size:1.55rem}.tbp-fact span{font-size:.65rem;text-transform:uppercase;letter-spacing:.12em}.tbp-story{max-width:900px;margin:auto;padding:clamp(70px,9vw,125px) 28px;text-align:center}.tbp-story h2,.tbp-section h2,.tbp-neighborhood h2,.tbp-contact h2{font-family:Georgia,serif;font-size:clamp(2.5rem,4.8vw,4.8rem);line-height:1.03;margin:.5rem 0 1.4rem}.tbp-story p,.tbp-copy p,.tbp-neighborhood p{font-size:1.06rem;line-height:1.8;color:#3f4650}.tbp-gallery{max-width:1280px;margin:auto;padding:0 28px 100px;display:grid;grid-template-columns:2fr 1fr 1fr;grid-template-rows:310px 310px;gap:16px}.tbp-gallery img{width:100%;height:100%;object-fit:cover}.tbp-gallery img:first-child{grid-row:1/3}.tbp-gallery img:nth-child(4){grid-column:2/4}.tbp-section{display:grid;grid-template-columns:1fr 1fr;min-height:620px}.tbp-section.reverse .tbp-image{order:2}.tbp-image{min-height:520px;background-size:cover;background-position:center}.tbp-copy{display:flex;flex-direction:column;justify-content:center;padding:clamp(45px,7vw,100px);background:#fff}.tbp-copy .tbp-kicker{color:#b46f88}.tbp-feature-list{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:20px 0 0;padding:0;list-style:none}.tbp-feature-list li{padding:12px 0;border-bottom:1px solid #dbc8b3;font-size:.87rem}.tbp-highlights{background:#344c6a;color:#fff;padding:clamp(70px,8vw,110px) 28px}.tbp-highlights-inner{max-width:1200px;margin:auto}.tbp-highlights h2{font-family:Georgia,serif;font-size:clamp(2.5rem,4.7vw,4.6rem);text-align:center;margin:.5rem 0 3rem}.tbp-highlight-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.tbp-highlight{border:1px solid rgba(255,255,255,.3);padding:28px}.tbp-highlight h3{font-family:Georgia,serif;font-size:1.45rem;color:#fff;margin:0 0 8px}.tbp-highlight p{line-height:1.65;margin:0;color:rgba(255,255,255,.82)}.tbp-video{max-width:1100px;margin:auto;padding:100px 28px;text-align:center}.tbp-video-box{aspect-ratio:16/9;background:#6f8a74;display:flex;align-items:center;justify-content:center;color:#fff}.tbp-video-box span{border:1px solid rgba(255,255,255,.7);padding:18px 25px;text-transform:uppercase;letter-spacing:.12em;font-size:.72rem}.tbp-neighborhood{display:grid;grid-template-columns:1.1fr .9fr;background:#dbc8b3}.tbp-neighborhood-copy{padding:clamp(50px,7vw,95px)}.tbp-map{min-height:480px;background:url(\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584-2.jpg\") center/cover no-repeat;position:relative}.tbp-map:after{content:\"MAP OR NEIGHBORHOOD IMAGE\";position:absolute;inset:auto 20px 20px;background:rgba(52,76,106,.9);color:#fff;padding:12px;text-align:center;font-size:.68rem;letter-spacing:.1em}.tbp-contact{display:grid;grid-template-columns:380px 1fr;max-width:1120px;margin:100px auto;padding:0 28px}.tbp-contact img{width:100%;height:100%;object-fit:cover}.tbp-contact-copy{background:#fff;padding:clamp(40px,6vw,80px);display:flex;flex-direction:column;justify-content:center}.tbp-contact-copy h2{font-size:clamp(2.4rem,4vw,4rem)}.tbp-note{max-width:900px;margin:0 auto 80px;padding:24px;background:#f1e6e9;border-left:6px solid #d6a3b5;color:#344c6a}.tbp-note strong{display:block;margin-bottom:7px}.tbp-note ul{margin-bottom:0}@media(max-width:850px){.tbp-hero{min-height:600px}.tbp-facts{grid-template-columns:repeat(2,1fr);padding-top:95px}.tbp-gallery{grid-template-columns:1fr 1fr;grid-template-rows:280px 220px 220px}.tbp-gallery img:first-child{grid-column:1/3;grid-row:auto}.tbp-gallery img:nth-child(4){grid-column:auto}.tbp-section,.tbp-neighborhood,.tbp-contact{grid-template-columns:1fr}.tbp-section.reverse .tbp-image{order:0}.tbp-highlight-grid{grid-template-columns:1fr}.tbp-contact{margin:60px auto}.tbp-contact img{max-height:520px}.tbp-feature-list{grid-template-columns:1fr}}.tb-property-template .tbp-map:after{display:none!important}.tbp-highlights h2{color:#fbf8f4!important}.tbp-showcase{display:grid;grid-template-columns:1.08fr .92fr;min-height:560px;background:#fff}.tbp-showcase-image{min-height:520px;background:center/cover no-repeat}.tbp-showcase-copy{display:flex;flex-direction:column;justify-content:center;padding:clamp(48px,7vw,95px)}.tbp-showcase-copy h2{font-family:Georgia,serif;font-size:clamp(2.5rem,4.5vw,4.5rem);line-height:1.03;margin:.5rem 0 1.2rem}.tbp-showcase-copy p{font-size:1.04rem;line-height:1.75;color:#3f4650}@media(max-width:850px){.tbp-showcase{grid-template-columns:1fr}.tbp-showcase-image{min-height:380px}}</style><div class=\"tb-property-template\"><section class=\"tbp-hero\"><div class=\"tbp-hero-card\"><span class=\"tbp-status\">ACTIVE</span><div class=\"tbp-kicker\">A Tanya Barrans Featured Listing</div><h1>18026 75th Avenue E<br>Puyallup, WA</h1><div class=\"tbp-price\">$545,000</div><div class=\"tbp-actions\"><a class=\"tbp-btn\" href=\"/contact/\">Schedule a Private Showing</a><a class=\"tbp-btn alt\" href=\"#property-story\">Explore the Home</a></div></div></section><section class=\"tbp-facts\"><div class=\"tbp-fact\"><strong>4</strong><span>Bedrooms</span></div><div class=\"tbp-fact\"><strong>2.5</strong><span>Bathrooms</span></div><div class=\"tbp-fact\"><strong>2,201</strong><span>Square feet</span></div><div class=\"tbp-fact\"><strong>0.08</strong><span>Acres</span></div><div class=\"tbp-fact\"><strong>2546584</strong><span>Listing number</span></div></section><section id=\"property-story\" class=\"tbp-story\"><div class=\"tbp-kicker\">The Property Story</div><h2>A home that makes room for the way life really happens</h2><p>With more than 2,200 square feet, four bedrooms, and a thoughtful layout, this home offers flexibility that keeps working as life changes. The covered porch faces a neighborhood park, while the open main floor makes space for busy mornings, homework at the island, guests, and movie nights by the gas fireplace.</p></section><section class=\"tbp-gallery\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584-1.jpg\" alt=\"18026 75th Avenue E in Puyallup\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584-2.jpg\" alt=\"18026 75th Avenue E in Puyallup\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584-24.jpg\" alt=\"18026 75th Avenue E in Puyallup\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584-25.jpg\" alt=\"18026 75th Avenue E in Puyallup\"></section><section class=\"tbp-section\"><div class=\"tbp-image\" style=\"background-image:url(https://assets.jlscontent.com/photos/wanwmls/254/658/2546584-4.jpg)\"></div><div class=\"tbp-copy\"><div class=\"tbp-kicker\">Inside the Home</div><h2>Comfortable spaces with room to adapt</h2><p>The main level flows from a generous entry into connected living, dining, and kitchen areas. A separate flex room can become a dining room, office, sitting room, or play space.</p><ul class=\"tbp-feature-list\"><li>Open-concept main floor</li><li>Four bedrooms upstairs</li><li>Gas fireplace</li><li>Flexible bonus room</li></ul></div></section><section class=\"tbp-section reverse\"><div class=\"tbp-image\" style=\"background-image:url(https://assets.jlscontent.com/photos/wanwmls/254/658/2546584-9.jpg)\"></div><div class=\"tbp-copy\"><div class=\"tbp-kicker\">Gather Here</div><h2>The kitchen at the center of it all</h2><p>Granite countertops, stainless appliances, abundant cabinetry, a corner pantry, and a spacious island give this kitchen room for meal prep, morning coffee, and lingering conversations.</p><ul class=\"tbp-feature-list\"><li>Stainless appliances</li><li>Granite countertops</li><li>Corner pantry + cabinetry</li><li>Large gathering island</li></ul></div></section><section class=\"tbp-section\"><div class=\"tbp-image\" style=\"background-image:url(https://assets.jlscontent.com/photos/wanwmls/254/658/2546584-13.jpg)\"></div><div class=\"tbp-copy\"><div class=\"tbp-kicker\">Room to Exhale</div><h2>A primary suite designed for unwinding</h2><p>The spacious primary suite includes a walk-in closet and private five-piece bath. Three additional bedrooms offer room for guests, hobbies, remote work, or a growing household.</p></div></section><section class=\"tbp-highlights\"><div class=\"tbp-highlights-inner\"><div class=\"tbp-kicker\" style=\"text-align:center;color:#d6a3b5\">The Details</div><h2>What makes this home stand out</h2><div class=\"tbp-highlight-grid\"><div class=\"tbp-highlight\"><h3>Fully fenced backyard</h3><p>A private patio and fenced yard create space for gardening, pets, play, summer meals, or a quiet evening outside.</p></div><div class=\"tbp-highlight\"><h3>Everyday convenience</h3><p>An attached two-car garage, upstairs laundry, generous storage, and an adaptable floor plan make routines easier.</p></div><div class=\"tbp-highlight\"><h3>Connected neighborhood living</h3><p>A porch overlooking the park, nearby schools, shopping, and commuter access support an easy rhythm.</p></div></div></div></section><section class=\"tbp-showcase\"><div class=\"tbp-showcase-image\" style=\"background-image:url(https://assets.jlscontent.com/photos/wanwmls/254/658/2546584-10.jpg)\"></div><div class=\"tbp-showcase-copy\"><div class=\"tbp-kicker\">Zillow Showcase + 3D Tour</div><h2>Walk through the home from wherever you are.</h2><p>Explore the rooms, layout, and flow in more detail with the immersive Zillow Showcase experience. It is the next best thing to stepping inside—then Tanya can arrange the real tour when you are ready.</p><div class=\"tbp-actions\"><a class=\"tbp-btn\" href=\"https://www.zillow.com/homedetails/18026-75th-Ave-E-Puyallup-WA-98375/102608323_zpid/\" target=\"_blank\" rel=\"noopener\">Launch the 3D Tour</a><a class=\"tbp-btn alt\" href=\"/contact/\">Schedule an In-Person Tour</a></div></div></section><section class=\"tbp-neighborhood\"><div class=\"tbp-neighborhood-copy\"><div class=\"tbp-kicker\">Around the Neighborhood</div><h2>Puyallup convenience with a neighborhood feel</h2><p>Near parks, shopping, dining, schools, and major routes, the home balances practical access with a welcoming residential setting.</p><a class=\"tbp-btn\" href=\"/contact/\">Ask Tanya About Puyallup</a></div><div class=\"tbp-map\"></div></section><section class=\"tbp-contact\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/07/gallery-2-new.jpg\" alt=\"Tanya Barrans\"><div class=\"tbp-contact-copy\"><div class=\"tbp-kicker\">Private Showings + Questions</div><h2>Let’s take a closer look.</h2><p>Want the disclosures, offer details, or a private tour? Tanya will make sure you have the context—not just the listing facts—to decide whether this home feels right.</p><div class=\"tbp-actions\"><a class=\"tbp-btn\" href=\"/contact/\">Ask Tanya About This Home</a><a class=\"tbp-btn alt\" href=\"tel:4255374728\">Call (425) 537-4728</a></div></div></section></div><!-- /wp:html -->', '18026 75th Avenue E | Puyallup, WA', '', 'publish', 'closed', 'closed', '', '18026-75th-avenue-e-puyallup-wa', '', '', '2026-08-20 06:36:48', '2026-08-20 06:36:48', '', 0, 'https://violet-wren-104886.hostingersite.com/?page_id=90224', 0, 'page', '', 0),
