(90233, 2, '2026-08-20 16:35:18', '2026-08-20 16:35:18', '<!-- wp:html -->\n<style>\nbody.page-id-9 .wp-block-post-title{display:none!important}\n.tb-listings-page{width:100vw;max-width:none!important;margin-left:calc(50% - 50vw);margin-top:-1px;overflow:hidden}\n.tb-listings-page-hero{position:relative;min-height:clamp(520px,63vw,720px);display:flex;align-items:flex-end;background:linear-gradient(90deg,rgba(30,50,75,.23),rgba(30,50,75,.02)),url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/renton-pending.jpg\') center 55%/cover no-repeat;overflow:hidden}\n.tb-listings-page-hero:after{content:\"\";position:absolute;inset:50% 0 0;background:linear-gradient(transparent,rgba(26,47,70,.2));pointer-events:none}\n.tb-listings-hero-card{position:relative;z-index:1;width:min(650px,calc(100% - 48px));margin:0 0 -54px max(5vw,24px);padding:clamp(34px,5vw,64px);background:#fbf7f1;color:#344c6a;box-shadow:0 24px 70px rgba(35,52,73,.2)}\n.tb-listings-kicker,.tb-listings-page .tb-eyebrow{font-size:.72rem!important;letter-spacing:.18em;text-transform:uppercase;font-weight:700;color:#b46f88!important}\n.tb-listings-hero-card h2{font-size:clamp(2.7rem,5.4vw,5.2rem);line-height:.92;margin:.5rem 0 1.25rem;letter-spacing:-.03em}\n.tb-listings-hero-card h2 em{color:#c27e98;font-weight:inherit}\n.tb-listings-hero-card p{font-size:clamp(1rem,1.3vw,1.18rem);line-height:1.7;max-width:540px}\n.tb-listings-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px}\n.tb-listings-btn{display:inline-block;padding:14px 22px;background:#344c6a;color:white!important;text-decoration:none!important;font-size:.76rem;font-weight:700;letter-spacing:.09em;text-transform:uppercase;border:1px solid #344c6a;transition:.2s}\n.tb-listings-btn.alt{background:transparent;color:#344c6a!important}\n.tb-listings-btn:hover{transform:translateY(-2px);background:#c27e98;border-color:#c27e98;color:white!important}\n.tb-listings-page #current-listings{padding-top:125px!important}\n.tb-lis