adding:20px;color:#fff!important;text-decoration:none;background-size:cover;background-position:center;border-radius:6px;box-shadow:inset 0 -110px 80px rgba(11,31,59,.78)}.tb-renton-category strong{font-size:1.05rem;letter-spacing:.08em;text-transform:uppercase}.tb-renton-guide-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.tb-renton-guide{display:grid;grid-template-columns:120px 1fr;gap:18px;align-items:center;padding:18px;background:#fff;border:1px solid #e4dccd;color:#1c2d4e!important;text-decoration:none}.tb-renton-guide img{width:120px;height:120px;object-fit:cover}.tb-renton-guide strong{font-family:Cormorant Garamond,serif;font-size:1.45rem;line-height:1.1}.tb-renton-guide span{display:block;margin-top:8px;color:#a97f06;font-size:.78rem;font-weight:700;text-transform:uppercase}@media(max-width:760px){.tb-renton-series-grid,.tb-renton-category-grid,.tb-renton-guide-grid{grid-template-columns:1fr}.tb-renton-category{min-height:210px}.tb-renton-series,.tb-renton-categories,.tb-renton-guides{padding:52px 20px}.tb-renton-stamp--official{width:118px;height:118px}}</style>\n	<!-- /wp:html -->\n\n	<!-- The Journal newsletter pattern is deliberately not reused here: it is\n	     styled for the Journal page and renders unreadably in this context.\n	     The blueprint asks for a Renton-specific signup with its own copy,\n	     which is a separate build. -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-renton\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/renton-hub\",\"name\":\"Renton Hub\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-renton\">\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-hero\" aria-labelledby=\"renton-title\">\n		<div class=\"tb-page-shell tb-renton-hero__inner\">\n						<img class=\"tb-renton-stamp tb-renton-stamp--official\" src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/ChatGPT_Image_Jul_27_2026_04_08_16_PM.png\" alt=\"Rooted in Renton, established 1981\" width=\"1254\" height=\"1254\">\n			<h1 id=\"renton-title\" class=\"tb-renton-title\">Rooted in Renton</h1>\n			<p class=\"tb-renton-dek\">Local stories, favorite places and the people who make Renton feel like home.</p>\n			<p class=\"tb-renton-hero__links\">\n				<a class=\"tb-renton-button\" href=\"#renton-latest\">Explore the latest stories</a>\n				<a class=\"tb-renton-link\" href=\"https://www.instagram.com/tanyabarrans/\" target=\"_blank\" rel=\"noopener noreferrer\">Watch the series <span aria-hidden=\"true\">&rarr;</span></a>\n			</p>\n		</div>\n	</section>\n	<!-- /wp:html -->\n\n	<!-- wp:group {\"className\":\"tb-renton-featured\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-renton-featured\">\n		<div class=\"tb-page-shell\">\n\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">Featured Story</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:query {\"queryId\":40,\"query\":{\"perPage\":1,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"include\",\"include\":[59],\"taxQuery\":{\"category\":[23]},\"inherit\":false},\"align\":\"wide\"} -->\n			<div class=\"wp-block-query alignwide\">\n				<!-- wp:post-template -->\n					<!-- wp:group {\"className\":\"tb-renton-feature-card\",\"layout\":{\"type\":\"default\"}} -->\n					<div class=\"wp-block-group tb-renton-feature-card\">\n						<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"16/9\"} /-->\n						<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-renton-kicker\"} /-->\n						<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"x-large\"} /-->\n						<!-- wp:post-excerpt {\"excerptLength\":34} /-->\n						<!-- wp:post-date {\"format\":\"F j, Y\",\"className\":\"tb-renton-date\"} /-->\n					</div>\n					<!-- /wp:group -->\n				<!-- /wp:post-template -->\n\n				<!-- wp:query-no-results -->\n					<!-- wp:paragraph {\"className\":\"tb-renton-empty\"} -->\n					<p class=\"tb-renton-empty\">The first Renton stories are being written now. In the meantime, tell Tanya what you would like to see covered — a favourite restaurant, a park worth knowing about, or a corner of the city that deserves more attention.</p>\n					<!-- /wp:paragraph -->\n\n					<!-- wp:buttons -->\n					<div class=\"wp-block-buttons\">\n						<!-- wp:button {\"backgroundColor\":\"ink\"} -->\n						<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-ink-background-color has-background wp-element-button\" href=\"/contact/\">Suggest a Renton story</a></div>\n						<!-- /wp:button -->\n					</div>\n					<!-- /wp:buttons -->\n				<!-- /wp:query-no-results -->\n			</div>\n			<!-- /wp:query -->\n\n		</div>\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-series\" id=\"renton-series\"><div class=\"tb-page-shell\"><h2 class=\"tb-renton-section-title\">Watch the Series</h2><div class=\"tb-renton-series-grid\"><a class=\"tb-renton-series-card\" href=\"https://www.instagram.com/tanyabarrans/\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\" alt=\"Downtown Renton\"><span class=\"tb-renton-play\" aria-hidden=\"true\">▶</span><small>ROOTED IN RENTON</small><strong>Made for More Than the Commute</strong></a><a class=\"tb-renton-series-card\" href=\"https://www.instagram.com/tanyabarrans/\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-kitchen-garden.jpg\" alt=\"A local garden and gathering place\"><span class=\"tb-renton-play\" aria-hidden=\"true\">▶</span><small>LOCAL PEOPLE</small><strong>The People Behind the Places</strong></a><a class=\"tb-renton-series-card\" href=\"https://www.instagram.com/tanyabarrans/\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg\" alt=\"A welcoming local gathering\"><span class=\"tb-renton-play\" aria-hidden=\"true\">▶</span><small>COMMUNITY</small><strong>A Community That Shows Up</strong></a></div><div class=\"tb-renton-actions\" style=\"justify-content:center\"><a class=\"tb-renton-action tb-renton-action--navy\" href=\"https://www.instagram.com/tanyabarrans/\" target=\"_blank\" rel=\"noopener noreferrer\">View all Rooted in Renton videos</a></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-categories\"><div class=\"tb-page-shell\"><h2 class=\"tb-renton-section-title\">Explore by Category</h2><div class=\"tb-renton-category-grid\"><a class=\"tb-renton-category\" href=\"/category/renton/eat-drink/\" style=\"background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg\')\"><strong>Eat &amp; Drink →</strong></a><a class=\"tb-renton-category\" href=\"/category/renton/parks-outdoors/\" style=\"background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-kitchen-garden.jpg\')\"><strong>Parks &amp; Outdoors →</strong></a><a class=\"tb-renton-category\" href=\"/category/renton/local-businesses/\" style=\"background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-front-door.jpg\')\"><strong>Local Businesses →</strong></a><a class=\"tb-renton-category\" href=\"/category/renton/community-events/\" style=\"background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\')\"><strong>Events →</strong></a></div></div></section>\n	<!-- /wp:html -->\n\n\n	<!-- wp:group {\"className\":\"tb-renton-latest\",\"layout\":{\"type\":\"default\"},\"anchor\":\"renton-latest\"} -->\n	<div class=\"wp-block-group tb-renton-latest\" id=\"renton-latest\">\n		<div class=\"tb-page-shell\">\n\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">More From Renton</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:query {\"queryId\":41,\"query\":{\"perPage\":6,\"pages\":0,\"offset\":1,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"taxQuery\":{\"category\":[23]},\"inherit\":false},\"align\":\"wide\"} -->\n			<div class=\"wp-block-query alignwide\">\n				<!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n					<!-- wp:group {\"className\":\"tb-card tb-renton-card\",\"layout\":{\"type\":\"default\"}} -->\n					<div class=\"wp-block-group tb-card tb-renton-card\">\n						<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"4/3\"} /-->\n						<!-- wp:group {\"className\":\"tb-renton-card__body\",\"layout\":{\"type\":\"default\"}} -->\n						<div class=\"wp-block-group tb-renton-card__body\">\n							<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-renton-kicker\"} /-->\n							<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"large\"} /-->\n							<!-- wp:post-date {\"format\":\"F j, Y\",\"className\":\"tb-renton-date\"} /-->\n						</div>\n						<!-- /wp:group -->\n					</div>\n					<!-- /wp:group -->\n				<!-- /wp:post-template -->\n\n				<!-- wp:query-no-results -->\n					<!-- wp:paragraph {\"className\":\"tb-renton-empty\"} -->\n					<p class=\"tb-renton-empty\">More Renton stories are on the way.</p>\n					<!-- /wp:paragraph -->\n				<!-- /wp:query-no-results -->\n			</div>\n			<!-- /wp:query -->\n\n		</div>\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-guides\"><div class=\"tb-page-shell\"><h2 class=\"tb-renton-section-title\">Renton Guide Collection</h2><div class=\"tb-renton-guide-grid\"><a class=\"tb-renton-guide\" href=\"/20-things-to-do-in-renton-this-weekend-from-someone-who-lives-here/\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\" alt=\"\"><div><strong>The Ultimate Renton Weekend Guide</strong><span>Read guide →</span></div></a><a class=\"tb-renton-guide\" href=\"/best-renton-neighborhoods-for-every-lifestyle-a-locals-honest-guide/\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-front-door.jpg\" alt=\"\"><div><strong>A Local\'s Guide to Renton Neighborhoods</strong><span>Read guide →</span></div></a><a class=\"tb-renton-guide\" href=\"/moving-to-renton-wa-a-practical-guide-to-planning-your-move/\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg\" alt=\"\"><div><strong>Moving to Renton: A Practical Guide</strong><span>Read guide →</span></div></a></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-editorial tb-renton-editorial--navy\"><div class=\"tb-page-shell\"><p class=\"tb-eyebrow\">Tanya\'s Current Renton Favorites</p><h2>A few places worth knowing right now.</h2><p class=\"tb-renton-editorial__intro\">Personal picks from around the city—the places, walks, and small businesses Tanya is genuinely enjoying and recommending.</p><div class=\"tb-renton-favorites\"><article class=\"tb-renton-favorite\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-kitchen-garden.jpg\" alt=\"\"><div><strong>The local plant shop</strong><span>Greenery, good advice, and a reason to linger.</span></div></article><article class=\"tb-renton-favorite\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\" alt=\"\"><div><strong>Downtown Renton</strong><span>The mural, independent businesses, and neighborhood character.</span></div></article><article class=\"tb-renton-favorite\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg\" alt=\"\"><div><strong>A cozy coffee stop</strong><span>A warm drink, a friendly corner, and time to catch up.</span></div></article><article class=\"tb-renton-favorite\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-hero.jpg\" alt=\"\"><div><strong>Renton Farmers Market</strong><span>Local finds, familiar faces, and a seasonal tradition.</span></div></article></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-editorial tb-renton-editorial--mustard\"><div class=\"tb-page-shell\"><p class=\"tb-eyebrow\">Neighborhood Connection</p><h2>Love the place? Explore what it is like to live nearby.</h2><p class=\"tb-renton-editorial__intro\">Connect the restaurants, parks, businesses, and everyday stories you discover here with Renton\'s neighborhoods.</p><div class=\"tb-renton-actions\"><a class=\"tb-renton-action tb-renton-action--navy\" href=\"/neighborhoods/\">Explore Renton neighborhoods</a><a class=\"tb-renton-action tb-renton-action--navy\" href=\"/best-renton-neighborhoods-for-every-lifestyle-a-locals-honest-guide/\">Read the neighborhood guide</a></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-editorial\"><div class=\"tb-page-shell\"><p class=\"tb-eyebrow\">Community Stories</p><h2>Know a Renton story we should tell?</h2><p class=\"tb-renton-editorial__intro\">Share a local business, community event, interesting person, hidden gem, or story idea. Rooted in Renton should be shaped by the people who call the city home.</p><div class=\"tb-renton-actions\"><a class=\"tb-renton-action\" href=\"/contact/\">Suggest a Renton story</a></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-cta\" aria-labelledby=\"renton-cta-title\">\n		<div class=\"tb-page-shell\">\n			<h2 id=\"renton-cta-title\">Thinking about making Renton home?</h2>\n			<p>Or making a move within the city? Tanya can walk you through the neighbourhoods and the market without the sales pressure.</p>\n			<p class=\"tb-renton-cta__links\">\n				<a class=\"tb-renton-button tb-renton-button--light\" href=\"/contact/\">Ask Tanya a question</a>\n				<a class=\"tb-renton-link tb-renton-link--light\" href=\"/buy/\">Explore buying in Renton <span aria-hidden=\"true\">&rarr;</span></a>\n			</p>\n		</div>\n	</section>\n	<!-- /wp:html -->\n\n</div>\n<!-- /wp:group -->\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'page-renton', '', 'inherit', 'closed', 'closed', '', '103-revision-v1', '', '', '2026-08-20 21:19:33', '2026-08-20 21:19:33', '', 103, 'https://violet-wren-104886.hostingersite.com/?p=90235', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(90236, 2, '2026-08-20 21:21:21', '2026-08-20 21:21:21', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- The hub supplies its own H1 inside the Rooted hero, so the page title is\n     not rendered here. Content comes from the Renton category, not this file. -->\n<!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-renton-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-renton-page\">\n	<!-- wp:html -->\n	<style>\n	.tb-renton-page{background:#fbf7ee;color:#243653}.tb-renton-hero{min-height:660px;display:flex;align-items:flex-end;background:linear-gradient(90deg,rgba(28,45,78,.94) 0%,rgba(28,45,78,.78) 52%,rgba(28,45,78,.22) 100%),url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\') center/cover no-repeat}.tb-renton-hero__inner{width:min(1180px,calc(100% - 48px));margin:auto;padding:72px 0}.tb-renton-stamp{width:132px;height:132px;margin-bottom:26px}.tb-renton-title{max-width:720px;margin:0 0 18px;color:#fff;font-size:clamp(3rem,7vw,5.5rem);line-height:.95}.tb-renton-dek{max-width:650px;color:#fff;font-size:clamp(1.1rem,2vw,1.35rem);line-height:1.65}.tb-renton-featured,.tb-renton-latest{padding:84px 24px}.tb-renton-featured .tb-page-shell,.tb-renton-latest .tb-page-shell,.tb-renton-editorial .tb-page-shell{max-width:1180px;margin:auto}.tb-renton-feature-card{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(280px,.7fr);gap:42px;align-items:center;background:#fff;padding:24px;border:1px solid #e4dccd}.tb-renton-feature-card .wp-block-post-featured-image{grid-row:1/6;margin:0}.tb-renton-feature-card:before{content:\"\";display:block;grid-column:1;grid-row:1/6;min-height:430px;background:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\') center/cover no-repeat}.tb-renton-feature-card>p,.tb-renton-feature-card>h2,.tb-rento